import{g as a,ad as e,r as n,A as t}from"./chunks/framework.CK2aBVEu.js";const u=JSON.parse('{"title":"Migration from v0","description":"","frontmatter":{"pageClass":"migration-page"},"headers":[],"relativePath":"docs/migration.md","filePath":"docs/migration.md","lastUpdated":1786562361000}'),p={name:"docs/migration.md"};function o(c,s,l,d,i,r){return e(),n("div",null,[...s[0]||(s[0]=[t(`<h1 id="migration-from-v0" tabindex="-1">Migration from v0 <a class="header-anchor" href="#migration-from-v0" aria-label="Permalink to “Migration from v0”">​</a></h1><p>A guide for moving an existing app onto <code>frappe-ui</code> v1. Work through one component family at a time. Each section opens with a before/after table. For the full change list see the <a href="/docs/changelog">changelog</a>; for the rationale behind each API see the <a href="https://github.com/frappe/frappe-ui/tree/main/v1-release" target="_blank" rel="noreferrer">v1 release specs</a>.</p><p>After each pass, <code>grep</code> for the old prop or slot name to catch anything missed, then test the flows you touched. Type-checking won&#39;t catch focus, slot renames, or visual regressions.</p><h2 id="what-this-guide-covers" tabindex="-1">What this guide covers <a class="header-anchor" href="#what-this-guide-covers" aria-label="Permalink to “What this guide covers”">​</a></h2><p>Every <strong>silent break</strong> has a before/after here: old code that still runs, still type-checks, and behaves differently. Vue drops an unknown prop or slot without a word, so those are the ones that reach production. Each is marked.</p><p><strong>Loud breaks</strong> — an import that stops resolving, a type that no longer exists — are listed in the <a href="/docs/changelog">changelog</a> and only appear here when the replacement needs explaining. If your build already names the file and the line, the changelog is the faster read.</p><p>Only the Tailwind token renames have a codemod (<code>tokens-v2</code>, see <a href="#tokens">Tokens</a>). Every component, prop and slot rename is a hand edit.</p><h3 id="sections" tabindex="-1">Sections <a class="header-anchor" href="#sections" aria-label="Permalink to “Sections”">​</a></h3><ul><li><strong>Overlays</strong> — <a href="#dialog">Dialog</a> · <a href="#popover-hovercard-tooltip">Popover / HoverCard / Tooltip</a> · <a href="#commandpalette">CommandPalette</a></li><li><strong>Pickers and selection</strong> — <a href="#datepicker-timepicker-family">DatePicker / TimePicker</a> · <a href="#monthpicker">MonthPicker</a> · <a href="#selection-family-dropdown-select-combobox-multiselect">Selection family</a> · <a href="#autocomplete-removed">Autocomplete</a> · <a href="#formcontrol-type-autocomplete-removed">FormControl <code>type=&quot;autocomplete&quot;</code></a></li><li><strong>Inputs and files</strong> — <a href="#inputs">Inputs</a> · <a href="#fileuploader">FileUploader</a></li><li><strong>Navigation and layout</strong> — <a href="#sidebar">Sidebar</a> · <a href="#tabs">Tabs</a> · <a href="#tabbuttons">TabButtons</a> · <a href="#pageheadermobile-family-slot-names">PageHeaderMobile</a> · <a href="#keyboardshortcut">KeyboardShortcut</a> · <a href="#divider">Divider</a></li><li><strong>Display</strong> — <a href="#alert">Alert</a> · <a href="#icons">Icons</a> · <a href="#tree">Tree</a> · <a href="#card-listitem-standalone-toast-removed">Card, ListItem, Toast</a></li><li><strong>Editor and charts</strong> — <a href="#editor">Editor</a> · <a href="#charts">Charts</a></li><li><strong>Data and transport</strong> — <a href="#data-fetching-usedoctype-uselist">useDoctype / useList</a> · <a href="#data-fetching-exports">Data-fetching exports</a> · <a href="#http-transport-and-the-frappeui-plugin">HTTP transport and the plugin</a> · <a href="#usecall-a-throwing-beforesubmit-now-cancels-the-submit"><code>beforeSubmit</code></a> · <a href="#composables-and-directives-renamed">Composables and directives</a> · <a href="#pagemetaplugin-removed">pageMetaPlugin</a></li><li><strong>Tokens and CSS</strong> — <a href="#tokens">Tokens</a> · <a href="#family-stylesheets-list-style-css-editor-style-css">Family stylesheets</a> · <a href="#hljs-theme-css-and-tailwind-tokens-js-removed"><code>hljs-theme.css</code> and <code>tailwind/tokens.js</code></a></li><li><strong>Moved, not removed</strong> — these four families changed an import path and nothing else: <a href="#listview-—-moved-to-frappe-ui-experimental">ListView</a> · <a href="#calendar-—-moved-to-frappe-ui-experimental">Calendar</a> · <a href="#charts-v1-—-moved-to-frappe-ui-experimental">Charts (v1)</a> · <a href="#sprite-icons-—-moved-to-frappe-ui-experimental">Sprite icons</a>. The v0 <code>TextEditor</code> family moved the same way — see <a href="#editor">Editor</a>.</li><li><strong>Removed subpaths</strong> — <a href="#frappe-ui-code-editor-removed"><code>frappe-ui/code-editor</code></a> · <a href="#frappe-ui-frappe-and-frappe-ui-drive-removed"><code>frappe-ui/frappe</code> and <code>frappe-ui/drive</code></a></li></ul><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to “Requirements”">​</a></h2><p>v1 requires <strong>Node <code>&gt;=20.19.0</code></strong> (<code>package.json</code> <code>engines</code>). The 0.1.x line declared no <code>engines</code> field at all, so this is a new floor rather than a raised one — a Node 18 image that built v0 fine now fails to install.</p><p>Vue and vue-router are unchanged: <code>vue &gt;=3.5.0</code> and <code>vue-router ^4.1.6</code> (<code>package.json</code> <code>peerDependencies</code>). An app already on v0 needs no Vue bump.</p><p>Tailwind stays on <strong>v3</strong>. <code>frappe-ui/tailwind</code> is a v3 preset and frappe-ui declares no <code>tailwindcss</code> peer dependency, so a v4 project installs cleanly and then fails at build time. See the <a href="/docs/foundations/tailwind">Tailwind page</a>.</p><p>v1 also depends on <strong><code>@vueuse/core</code> <code>^14.1.0</code></strong>, up from <code>^10.4.1</code> in the 0.1.x line. VueUse 14 requires Vue <code>^3.5.0</code>, which v1 already requires. If your app depends on <code>@vueuse/core</code> directly, move it to <code>^14</code> as well. Two major ranges in one app install two copies of the library, and a <code>resolve.dedupe</code> entry for <code>@vueuse/core</code> then collapses them onto whichever copy wins. That breaks the components which expect the newer one.</p><h2 id="dialog" tabindex="-1">Dialog <a class="header-anchor" href="#dialog" aria-label="Permalink to “Dialog”">​</a></h2><p>The <code>options</code> blob is flattened into top-level props. See the <a href="./components/dialog">Dialog</a> component page for the full API.</p><table tabindex="0"><thead><tr><th>Before</th><th>After</th></tr></thead><tbody><tr><td><code>v-model=&quot;show&quot;</code></td><td><code>v-model:open=&quot;show&quot;</code></td></tr><tr><td><code>:options=&quot;{ title, size, actions }&quot;</code></td><td><code>title</code> / <code>size</code> / <code>:actions</code></td></tr><tr><td><code>disableOutsideClickToClose</code></td><td><code>:dismissible=&quot;false&quot;</code></td></tr><tr><td><code>&lt;template #body-content&gt;</code></td><td>default slot</td></tr><tr><td><code>&lt;template #body-main&gt;</code></td><td>default slot</td></tr><tr><td><code>&lt;template #body-title&gt;</code></td><td><code>&lt;template #title&gt;</code></td></tr><tr><td><code>&lt;template #body-header&gt;</code></td><td><code>&lt;template #title&gt;</code> (no direct replacement)</td></tr><tr><td><code>&lt;template #body&gt;</code></td><td><code>bare</code> prop + default slot</td></tr><tr><td><code>onClick: (close) =&gt; …</code></td><td><code>onClick: ({ close }) =&gt; …</code></td></tr><tr><td><code>:icon=&quot;{ appearance: &#39;warning&#39; }&quot;</code></td><td><code>:icon=&quot;{ theme: &#39;amber&#39; }&quot;</code></td></tr><tr><td><code>dialogRef.close()</code></td><td><code>v-model:open</code> / <code>close</code> slot prop</td></tr><tr><td>manual focus hacks / <code>v-focus</code></td><td><code>autofocus</code> attr on a descendant</td></tr></tbody></table><p>Most of this table is <strong>silent</strong>: Vue drops an unknown prop or slot with no error, so the dialog renders with no title, no actions, or an empty body, and a leftover <code>:disable-outside-click-to-close</code> quietly becomes dismissible. Two rows are loud instead — <code>onClick: (close) =&gt; close()</code> throws <code>TypeError: close is not a function</code>, and a template-ref <code>.close()</code> throws the same way. <code>v-model</code> itself still works (<code>modelValue</code> is kept as a second binding), but <code>open</code> is canonical and wins when both are bound.</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Dialog</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">options</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_13ahmt">{</span><span class="s_r4oegk"> title</span><span class="s_1jjt6x">: </span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">Edit Item</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> }</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> v-model</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">show</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;template #body-content&gt;</span></span>
<span class="line"><span class="s_6am9cx">    &lt;FormControl label=&quot;Name&quot; v-model=&quot;item.name&quot; /&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;/template&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;template #actions&gt;</span></span>
<span class="line"><span class="s_6am9cx">    &lt;Button variant=&quot;solid&quot; @click=&quot;save&quot;&gt;Save&lt;/Button&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;/template&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">Dialog</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Dialog</span><span class="s_1i4ay4"> title</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">Edit Item</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> v-model</span><span class="s_1jjt6x">:</span><span class="s_1i4ay4">open</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">show</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;FormControl label=&quot;Name&quot; v-model=&quot;item.name&quot; /&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;template #actions&gt;</span></span>
<span class="line"><span class="s_6am9cx">    &lt;Button variant=&quot;solid&quot; @click=&quot;save&quot;&gt;Save&lt;/Button&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;/template&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">Dialog</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p>For reactive <code>:options</code> objects, spread them: <code>&lt;Dialog v-bind=&quot;opts || {}&quot; /&gt;</code>. For the imperative API, use <code>dialog.confirm</code> / <code>dialog.danger</code> / <code>dialog.prompt</code> from <code>frappe-ui</code> (callback-based: <code>onConfirm</code> resolves to close, throws to stay open) and wrap your app root in <code>&lt;FrappeUIProvider&gt;</code>.</p><h3 id="icon-appearance-→-icon-theme" tabindex="-1"><code>icon.appearance</code> → <code>icon.theme</code> <a class="header-anchor" href="#icon-appearance-→-icon-theme" aria-label="Permalink to “icon.appearance → icon.theme”">​</a></h3><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Dialog</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">icon</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_13ahmt">{</span><span class="s_r4oegk"> name</span><span class="s_1jjt6x">: </span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">lucide-alert-triangle</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">, </span><span class="s_r4oegk">appearance</span><span class="s_1jjt6x">: </span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">warning</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> }</span><span class="s_w1p9wo">&quot;</span><span class="s_1jjt6x"> ...</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Dialog</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">icon</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_13ahmt">{</span><span class="s_r4oegk"> name</span><span class="s_1jjt6x">: </span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">lucide-alert-triangle</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">, </span><span class="s_r4oegk">theme</span><span class="s_1jjt6x">: </span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">amber</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> }</span><span class="s_w1p9wo">&quot;</span><span class="s_1jjt6x"> ...</span><span class="s_1zd9e2"> /&gt;</span></span></code></pre></div><p><code>appearance</code> is dropped silently — Vue accepts the unknown key with no error, so the icon renders with no tone. Map <code>warning → amber</code>, <code>info → blue</code>, <code>danger → red</code>, <code>success → green</code>.</p><h3 id="theme-yellow-→-theme-amber" tabindex="-1"><code>theme: &#39;yellow&#39;</code> → <code>theme: &#39;amber&#39;</code> <a class="header-anchor" href="#theme-yellow-→-theme-amber" aria-label="Permalink to “theme: &#39;yellow&#39; → theme: &#39;amber&#39;”">​</a></h3><p>The warning tone is <code>amber</code>, matching <code>Alert</code>, <code>SidebarCard</code>, <code>Badge</code> and <code>Avatar</code>. <code>Dialog</code> was the last component spelling it <code>yellow</code>, and it already rendered that value with the amber tokens — only the word changes, not the color.</p><table tabindex="0"><thead><tr><th>Before</th><th>After</th></tr></thead><tbody><tr><td><code>:icon=&quot;{ theme: &#39;yellow&#39; }&quot;</code></td><td><code>:icon=&quot;{ theme: &#39;amber&#39; }&quot;</code></td></tr><tr><td><code>dialog.confirm({ theme: &#39;yellow&#39; })</code></td><td><code>dialog.confirm({ theme: &#39;amber&#39; })</code></td></tr></tbody></table><p>This is a <strong>silent break</strong> for JavaScript call sites: <code>yellow</code> is no longer a key in the tone maps, so the icon renders with no tone and nothing throws. TypeScript call sites get a union error.</p><h3 id="a-template-ref-no-longer-exposes-close" tabindex="-1">A template ref no longer exposes <code>close()</code> <a class="header-anchor" href="#a-template-ref-no-longer-exposes-close" aria-label="Permalink to “A template ref no longer exposes close()”">​</a></h3><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Dialog</span><span class="s_1i4ay4"> ref</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">dialogRef</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> v-model</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">show</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1i4ay4"> setup</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_22m8k2">dialogRef</span><span class="s_1jjt6x">.</span><span class="s_11933w">value</span><span class="s_1jjt6x">.</span><span class="s_indoxt">close</span><span class="s_13ahmt">()</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Dialog</span><span class="s_1i4ay4"> v-model</span><span class="s_1jjt6x">:</span><span class="s_1i4ay4">open</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">show</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1i4ay4"> setup</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_22m8k2">show</span><span class="s_1jjt6x">.</span><span class="s_11933w">value</span><span class="s_2ekfrt"> =</span><span class="s_40mev6"> false</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p><code>Dialog</code> exposes nothing on its template ref (ADR-0012); calling <code>.close()</code> now throws. Drive <code>open</code> through <code>v-model:open</code>, or use the <code>close</code> slot prop from inside <code>#default</code> / <code>#actions</code>.</p><h2 id="datepicker-timepicker-family" tabindex="-1">DatePicker / TimePicker family <a class="header-anchor" href="#datepicker-timepicker-family" aria-label="Permalink to “DatePicker / TimePicker family”">​</a></h2><p>Covers <code>DatePicker</code>, <code>DateRangePicker</code>, <code>DateTimePicker</code>, and <code>TimePicker</code>. They share the popover-trigger vocabulary. Every removed prop and slot below is deleted, not aliased — and nothing warns at the tag: an unknown prop lands as an inert attribute, a renamed slot stops rendering. <code>grep</code> for each old name after upgrading.</p><table tabindex="0"><thead><tr><th>Before</th><th>After</th></tr></thead><tbody><tr><td><code>:value</code> prop</td><td><code>v-model</code></td></tr><tr><td><code>placement=&quot;bottom-start&quot;</code></td><td><code>side</code> + <code>align</code> + <code>offset</code></td></tr><tr><td><code>:autoClose</code></td><td><code>:keepOpen</code> (inverted)</td></tr><tr><td><code>allowCustom</code> / picker-level <code>readonly</code></td><td><code>typeable</code></td></tr><tr><td><code>inputClass</code></td><td><code>class</code></td></tr><tr><td><code>minTime</code>/<code>maxTime</code> (TimePicker), <code>minDateTime</code>/<code>maxDateTime</code> (DateTimePicker)</td><td><code>min</code> / <code>max</code></td></tr><tr><td><code>#target</code> (DatePicker, DateRangePicker, DateTimePicker)</td><td><code>#trigger</code> — TimePicker has neither</td></tr><tr><td><code>TimePicker.scrollMode</code></td><td>nothing — list is always centered</td></tr><tr><td><code>TimePicker.use12Hour</code></td><td><code>format=&quot;h:mm A&quot;</code></td></tr></tbody></table><p><code>@change</code> still fires alongside <code>@update:modelValue</code> — it wasn&#39;t deprecated and doesn&#39;t need replacing.</p><p>Most of the table above is a <strong>silent break</strong>: an old prop name that&#39;s no longer in the component&#39;s types lands as an inert extra attribute (or, for <code>min</code>/<code>max</code> aliases, the constraint just stops being enforced) instead of throwing. TypeScript callers get a compile error instead. <code>#target</code> is the one slot case — content in a leftover <code>&lt;template #target&gt;</code> silently stops rendering.</p><h3 id="trigger-slot-props" tabindex="-1">Trigger slot props <a class="header-anchor" href="#trigger-slot-props" aria-label="Permalink to “Trigger slot props”">​</a></h3><p><code>#trigger</code>, <code>#prefix</code> and <code>#suffix</code> receive <code>{ open, toggle }</code> — the same two names <code>Popover</code>, <code>HoverCard</code>, <code>Dropdown</code>, <code>Select</code>, <code>Combobox</code> and <code>MultiSelect</code> hand out. <code>TimePicker</code>&#39;s <code>#suffix</code> follows.</p><table tabindex="0"><thead><tr><th>Before</th><th>After</th></tr></thead><tbody><tr><td><code>isOpen</code></td><td><code>open</code></td></tr><tr><td><code>togglePopover</code></td><td><code>toggle</code></td></tr></tbody></table><p><code>displayLabel</code> and <code>inputValue</code> are unchanged, and <code>#actions</code> already used <code>close</code> — that stays too.</p><p><code>toggle</code> also takes <code>Popover</code>&#39;s signature, <code>(flag?: boolean | Event) =&gt; void</code>: a bare call flips, a boolean sets, and a DOM event is ignored. <code>togglePopover</code> only ever flipped, so nothing that worked before behaves differently.</p><p>This is a <strong>silent break</strong>: a destructured <code>isOpen</code> becomes <code>undefined</code>, so a class bound to it stops applying with no error, and <code>togglePopover()</code> throws <code>togglePopover is not a function</code> only if you call it.</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">template</span><span class="s_1jjt6x"> #</span><span class="s_1i4ay4">trigger</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_13ahmt">{</span><span class="s_22m8k2"> togglePopover</span><span class="s_1jjt6x">, </span><span class="s_22m8k2">isOpen</span><span class="s_13ahmt"> }</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">  &lt;</span><span class="s_1uuh8p">Button</span><span class="s_1i4ay4"> :class</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">isOpen &amp;&amp; &#39;ring-2&#39;</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> label</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">Pick a date</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> @click</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">togglePopover</span><span class="s_w1p9wo">&quot;</span><span class="s_28rvie"> /</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">template</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">template</span><span class="s_1jjt6x"> #</span><span class="s_1i4ay4">trigger</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_13ahmt">{</span><span class="s_22m8k2"> toggle</span><span class="s_1jjt6x">, </span><span class="s_22m8k2">open</span><span class="s_13ahmt"> }</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">  &lt;</span><span class="s_1uuh8p">Button</span><span class="s_1i4ay4"> :class</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">open &amp;&amp; &#39;ring-2&#39;</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> label</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">Pick a date</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> @click</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">toggle</span><span class="s_w1p9wo">&quot;</span><span class="s_28rvie"> /</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">template</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p>Behavior changes that apply even if you don&#39;t touch your code:</p><ul><li><code>DateRangePicker</code> emits a <code>[from, to]</code> tuple. Update handlers that called <code>.split(&#39;,&#39;)</code> on the value.</li><li><code>DateRangePicker.modelValue</code> is <code>string[]</code> on the way in too. A stored v0 <code>&quot;from,to&quot;</code> string is read positionally, so the picker silently opens with nothing selected. Convert stored values with <code>.split(&#39;,&#39;)</code> before binding.</li><li><code>DateTimePicker</code> no longer auto-closes on date click. Close from <code>@update:modelValue</code> or add an <code>#actions</code> Apply button.</li><li>The popover footer and auto Clear button were removed. Render an explicit Clear inside <code>#actions</code> if you relied on it.</li><li><code>DateRangePicker.clearable</code> now defaults to <code>true</code>, and nothing on <code>DateRangePicker</code> reads it — emptying the input always clears the range. <code>DatePicker</code> and <code>DateTimePicker</code> still honour <code>:clearable=&quot;false&quot;</code>.</li><li><code>useDatePicker</code> and its helpers (<code>getDate</code>, <code>getDatesAfter</code>, <code>getDaysInMonth</code>, <code>isLeapYear</code>) are deleted — the import fails. Nothing in the picker components used them; drop the import.</li></ul><h2 id="monthpicker" tabindex="-1">MonthPicker <a class="header-anchor" href="#monthpicker" aria-label="Permalink to “MonthPicker”">​</a></h2><p><code>MonthPicker</code> is deleted — the import fails.</p><p>Its model was one string holding <strong>both</strong> parts, <code>&quot;&lt;Month&gt; &lt;Year&gt;&quot;</code> (for example <code>&quot;January 2026&quot;</code>), written by a popover that toggled between a month grid and a year grid. Nothing in v1 reproduces that, so pick the replacement that matches what your code reads off the value:</p><ul><li>Month <strong>and</strong> year: use <code>DatePicker</code> and format the value yourself, or pair two <code>Select</code>s.</li><li>Month only: use <code>Select</code> with month options.</li></ul><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">MonthPicker</span><span class="s_1i4ay4"> v-model</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">month</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"><span class="s_1th9sy">&lt;!-- month === &#39;January 2026&#39; --&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Select</span></span>
<span class="line"><span class="s_1i4ay4">  v-model</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">month</span><span class="s_w1p9wo">&quot;</span></span>
<span class="line"><span class="s_1jjt6x">  :</span><span class="s_1i4ay4">options</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_13ahmt">[</span></span>
<span class="line"><span class="s_13ahmt">    {</span><span class="s_r4oegk"> label</span><span class="s_1jjt6x">: </span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">January</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">, </span><span class="s_r4oegk">value</span><span class="s_1jjt6x">: </span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">01</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> }</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">    {</span><span class="s_r4oegk"> label</span><span class="s_1jjt6x">: </span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">February</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">, </span><span class="s_r4oegk">value</span><span class="s_1jjt6x">: </span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">02</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> }</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_1th9sy">    // ...</span></span>
<span class="line"><span class="s_13ahmt">  ]</span><span class="s_w1p9wo">&quot;</span></span>
<span class="line"><span class="s_6am9cx">/&gt;</span></span>
<span class="line"><span class="s_6am9cx">&lt;!-- month === &#39;01&#39; — the year is no longer part of the value --&gt;</span></span></code></pre></div><h2 id="selection-family-dropdown-select-combobox-multiselect" tabindex="-1">Selection family (Dropdown / Select / Combobox / MultiSelect) <a class="header-anchor" href="#selection-family-dropdown-select-combobox-multiselect" aria-label="Permalink to “Selection family (Dropdown / Select / Combobox / MultiSelect)”">​</a></h2><p>Upgrade all three pickers together. They share an option shape and a slot vocabulary, and most apps use more than one.</p><p>Nothing here was deleted for an alias — the removed props, option keys and slot props are gone outright. Most fail quietly; see each subsection.</p><h3 id="shared" tabindex="-1">Shared <a class="header-anchor" href="#shared" aria-label="Permalink to “Shared”">​</a></h3><table tabindex="0"><thead><tr><th>Before</th><th>After</th></tr></thead><tbody><tr><td>Dropdown <code>{ group, items }</code></td><td><code>{ group, options }</code></td></tr><tr><td><code>#option</code> slot</td><td><code>#item-label</code>, plus <code>#item-prefix</code> for icons</td></tr><tr><td><code>option</code> item slot prop</td><td><code>item</code></td></tr><tr><td><code>clearAll</code> slot prop</td><td><code>clear</code></td></tr><tr><td>chevron / trailing content</td><td><code>#suffix</code> slot (replaces the chevron)</td></tr></tbody></table><p>Option values are <code>string | number</code> everywhere. <code>Select</code> no longer accepts <code>bigint</code> or object values.</p><h3 id="select" tabindex="-1">Select <a class="header-anchor" href="#select" aria-label="Permalink to “Select”">​</a></h3><table tabindex="0"><thead><tr><th>Before</th><th>After</th></tr></thead><tbody><tr><td><code>displayValue</code> trigger slot prop</td><td><code>selectedOption.label</code></td></tr><tr><td><code>data-slot=&quot;trigger-value&quot;</code></td><td>nothing — it marked an invisible element used to measure</td></tr></tbody></table><h3 id="combobox" tabindex="-1">Combobox <a class="header-anchor" href="#combobox" aria-label="Permalink to “Combobox”">​</a></h3><table tabindex="0"><thead><tr><th>Before</th><th>After</th></tr></thead><tbody><tr><td><code>slotName</code> on custom options</td><td><code>slot</code>, which dispatches to <code>#item-&lt;slot&gt;</code></td></tr><tr><td><code>searchTerm</code> in the custom-option context</td><td><code>query</code></td></tr><tr><td><code>input</code> emit</td><td><code>@update:query</code></td></tr><tr><td><code>render</code> on options</td><td><code>slots</code></td></tr><tr><td><code>placement</code>, <code>ComboboxPlacement</code></td><td><code>side</code> + <code>align</code></td></tr><tr><td><code>allowCustomValue</code></td><td><code>type: &#39;custom&#39;</code> option + <code>condition</code></td></tr><tr><td><code>reset()</code> on a template ref</td><td><code>clear()</code></td></tr><tr><td><code>SimpleOption</code>, <code>GroupedOption</code>, <code>SelectableOption</code>, <code>CustomOption</code></td><td>the <code>Combobox</code>-prefixed names</td></tr></tbody></table><h3 id="multiselect" tabindex="-1">MultiSelect <a class="header-anchor" href="#multiselect" aria-label="Permalink to “MultiSelect”">​</a></h3><table tabindex="0"><thead><tr><th>Before</th><th>After</th></tr></thead><tbody><tr><td><code>compareFn</code> prop</td><td>nothing — an option is selected when its <code>value</code> is in <code>modelValue</code></td></tr><tr><td><code>displayValue</code> slot prop</td><td><code>summary</code> on <code>#summary</code>, or <code>selectedOptions</code></td></tr><tr><td><code>toggleOpen</code> slot prop</td><td><code>setOpen(boolean)</code></td></tr></tbody></table><h3 id="dropdown-and-contextmenu" tabindex="-1">Dropdown and ContextMenu <a class="header-anchor" href="#dropdown-and-contextmenu" aria-label="Permalink to “Dropdown and ContextMenu”">​</a></h3><table tabindex="0"><thead><tr><th>Before</th><th>After</th></tr></thead><tbody><tr><td><code>placement</code> prop, <code>DropdownPlacement</code> type</td><td><code>align</code></td></tr><tr><td><code>{ group, items }</code></td><td><code>{ group, options }</code></td></tr><tr><td><code>component:</code> option rows</td><td><code>slots: { item: fn }</code></td></tr><tr><td><code>DropdownExposed</code> type</td><td>nothing — it described a template ref surface that never existed; use <code>v-model:open</code> or the <code>close</code> slot prop</td></tr></tbody></table><p>All three behavioral removals are silent in plain-JS apps — the old code still runs and renders wrong instead of failing — so check each one. TypeScript callers get errors instead: <code>items</code> and <code>component</code> stay in the option types as <code>never</code>, and <code>placement</code> is gone from <code>DropdownProps</code> altogether. A dev-mode console warning also fires when <code>placement</code>, <code>items</code> or <code>component</code> reaches the menu at runtime.</p><p><strong><code>placement</code> is ignored now.</strong> The menu falls back to <code>align=&quot;start&quot;</code>, so a right-aligned menu quietly moves left:</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Dropdown</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">options</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">options</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> placement</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">right</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Dropdown</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">options</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">options</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> placement</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">center</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Dropdown</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">options</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">options</span><span class="s_w1p9wo">&quot;</span><span class="s_suc1p8"> align</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">end</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Dropdown</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">options</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">options</span><span class="s_w1p9wo">&quot;</span><span class="s_suc1p8"> align</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">center</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span></code></pre></div><p><strong>A <code>{ group, items }</code> entry disappears</strong> — the group resolves to zero options and is dropped, leaving the rest of the menu intact:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">// Before</span></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> actions</span><span class="s_2ekfrt"> =</span><span class="s_13ahmt"> [{</span><span class="s_r4oegk"> group</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">Edit</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_r4oegk"> items</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> [{</span><span class="s_r4oegk"> label</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">Rename</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_r4oegk"> onClick</span><span class="s_1jjt6x">:</span><span class="s_11933w"> rename</span><span class="s_13ahmt"> }]</span><span class="s_13ahmt"> }]</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">// After</span></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> actions</span><span class="s_2ekfrt"> =</span><span class="s_13ahmt"> [{</span><span class="s_r4oegk"> group</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">Edit</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_r4oegk"> options</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> [{</span><span class="s_r4oegk"> label</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">Rename</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_r4oegk"> onClick</span><span class="s_1jjt6x">:</span><span class="s_11933w"> rename</span><span class="s_13ahmt"> }]</span><span class="s_13ahmt"> }]</span></span></code></pre></div><p><strong>A <code>component:</code> row renders as a plain action row</strong> using its <code>label</code>, which for most of these rows is empty:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">// Before</span></span>
<span class="line"><span class="s_13ahmt">{ </span><span class="s_g1fsda">component</span><span class="s_1jjt6x">:</span><span class="s_indoxt"> h</span><span class="s_13ahmt">(</span><span class="s_22m8k2">Button</span><span class="s_1jjt6x">,</span><span class="s_13ahmt"> { </span><span class="s_r4oegk">theme</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">red</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> }</span><span class="s_1jjt6x">,</span><span class="s_13ahmt"> () </span><span class="s_50ecpt">=&gt;</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">Delete</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt">) }</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">// After</span></span>
<span class="line"><span class="s_13ahmt">{</span></span>
<span class="line"><span class="s_g1fsda">  label</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">Delete</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_g1fsda">  slots</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_g1fsda">    item</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> () </span><span class="s_50ecpt">=&gt;</span><span class="s_indoxt"> h</span><span class="s_13ahmt">(</span><span class="s_22m8k2">Button</span><span class="s_1jjt6x">,</span><span class="s_13ahmt"> { </span><span class="s_r4oegk">theme</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">red</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> }</span><span class="s_1jjt6x">,</span><span class="s_13ahmt"> () </span><span class="s_50ecpt">=&gt;</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">Delete</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt">)</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">  }</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">}</span></span></code></pre></div><p>These apply identically to <code>ContextMenu</code>, which shares the option shape (<code>ContextMenuComponentOption</code> is removed with <code>DropdownComponentOption</code>).</p><h3 id="custom-rows" tabindex="-1">Custom rows <a class="header-anchor" href="#custom-rows" aria-label="Permalink to “Custom rows”">​</a></h3><p><code>Select</code> and <code>MultiSelect</code> lost <code>#option</code>; <code>Combobox</code> and <code>MultiSelect</code> lost <code>render</code> and <code>slotName</code>. They were the same idea — hand the whole row to the consumer. All three are replaced by region slots on a row the component owns.</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before: one slot for the whole label area --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Select</span><span class="s_1i4ay4"> v-model</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">chartType</span><span class="s_w1p9wo">&quot;</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">options</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">options</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;template #option=&quot;{ option }&quot;&gt;</span></span>
<span class="line"><span class="s_6am9cx">    &lt;div class=&quot;flex items-center gap-2&quot;&gt;</span></span>
<span class="line"><span class="s_6am9cx">      &lt;component :is=&quot;option.icon&quot; class=&quot;size-4&quot; /&gt;</span></span>
<span class="line"><span class="s_6am9cx">      &lt;span&gt;{{ option.label }}&lt;/span&gt;</span></span>
<span class="line"><span class="s_6am9cx">    &lt;/div&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;/template&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">Select</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After: one slot per region --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Select</span><span class="s_1i4ay4"> v-model</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">chartType</span><span class="s_w1p9wo">&quot;</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">options</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">options</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;template #item-prefix=&quot;{ item }&quot;&gt;</span></span>
<span class="line"><span class="s_6am9cx">    &lt;component :is=&quot;item.icon&quot; class=&quot;size-4&quot; /&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;/template&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;template #item-label=&quot;{ item }&quot;&gt;{{ item.label }}&lt;/template&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">Select</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p>An icon is rendered from <code>option.icon</code> automatically now, so the common case needs no slot at all — set <code>icon</code> and drop both templates.</p><p><code>Combobox</code>&#39;s <code>render</code> moves the same way: the function form becomes <code>slots.item</code>, and the object form maps to <code>slots</code> key for key. Use these for lists built in JavaScript, where no template is in reach:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> users</span><span class="s_2ekfrt"> =</span><span class="s_22m8k2"> fetchedUsers</span><span class="s_1jjt6x">.</span><span class="s_indoxt">map</span><span class="s_13ahmt">((</span><span class="s_fsg3al">user</span><span class="s_13ahmt">)</span><span class="s_50ecpt"> =&gt;</span><span class="s_13ahmt"> ({</span></span>
<span class="line"><span class="s_r4oegk">  label</span><span class="s_1jjt6x">:</span><span class="s_22m8k2"> user</span><span class="s_1jjt6x">.</span><span class="s_11933w">name</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">  value</span><span class="s_1jjt6x">:</span><span class="s_22m8k2"> user</span><span class="s_1jjt6x">.</span><span class="s_11933w">id</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">  slots</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_indoxt">    prefix</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> (</span><span class="s_1jjt6x">{</span><span class="s_fsg3al"> item</span><span class="s_1jjt6x"> }</span><span class="s_13ahmt">)</span><span class="s_50ecpt"> =&gt;</span><span class="s_indoxt"> h</span><span class="s_13ahmt">(</span><span class="s_22m8k2">Avatar</span><span class="s_1jjt6x">,</span><span class="s_13ahmt"> {</span><span class="s_12xt1b"> image</span><span class="s_1jjt6x">:</span><span class="s_22m8k2"> item</span><span class="s_1jjt6x">.</span><span class="s_11933w">image</span><span class="s_1jjt6x">,</span><span class="s_12xt1b"> class</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">size-4</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> })</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">  }</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">}))</span></span></code></pre></div><p>Full-row takeover is still there — <code>slots.item</code>, or the <code>#item</code> template slot.</p><h3 id="custom-options-on-combobox" tabindex="-1">Custom options on Combobox <a class="header-anchor" href="#custom-options-on-combobox" aria-label="Permalink to “Custom options on Combobox”">​</a></h3><p>Two renames land on the same option object:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">// Before</span></span>
<span class="line"><span class="s_13ahmt">{</span></span>
<span class="line"><span class="s_g1fsda">  type</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">custom</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_g1fsda">  key</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">create-new</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_g1fsda">  slotName</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">create-new</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_g1fsda">  onClick</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> (</span><span class="s_1jjt6x">{</span><span class="s_fsg3al"> searchTerm</span><span class="s_1jjt6x"> }</span><span class="s_13ahmt">) </span><span class="s_50ecpt">=&gt;</span><span class="s_indoxt"> createItem</span><span class="s_13ahmt">(</span><span class="s_22m8k2">searchTerm</span><span class="s_13ahmt">)</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_g1fsda">  condition</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> (</span><span class="s_1jjt6x">{</span><span class="s_fsg3al"> searchTerm</span><span class="s_1jjt6x"> }</span><span class="s_13ahmt">) </span><span class="s_50ecpt">=&gt;</span><span class="s_indoxt"> Boolean</span><span class="s_13ahmt">(</span><span class="s_22m8k2">searchTerm</span><span class="s_13ahmt">)</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">}</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">// After</span></span>
<span class="line"><span class="s_13ahmt">{</span></span>
<span class="line"><span class="s_g1fsda">  type</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">custom</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_g1fsda">  key</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">create-new</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_g1fsda">  slot</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">create-new</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_g1fsda">  onClick</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> (</span><span class="s_1jjt6x">{</span><span class="s_fsg3al"> query</span><span class="s_1jjt6x"> }</span><span class="s_13ahmt">) </span><span class="s_50ecpt">=&gt;</span><span class="s_indoxt"> createItem</span><span class="s_13ahmt">(</span><span class="s_22m8k2">query</span><span class="s_13ahmt">)</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_g1fsda">  condition</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> (</span><span class="s_1jjt6x">{</span><span class="s_fsg3al"> query</span><span class="s_1jjt6x"> }</span><span class="s_13ahmt">) </span><span class="s_50ecpt">=&gt;</span><span class="s_indoxt"> Boolean</span><span class="s_13ahmt">(</span><span class="s_22m8k2">query</span><span class="s_13ahmt">)</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">}</span></span></code></pre></div><p>The slot the row lands in is renamed with it. <code>#create-new</code> becomes <code>#item-create-new</code>, and it receives <code>{ item, query, selected }</code> instead of <code>{ option, searchTerm }</code>. <code>onClick</code> and <code>condition</code> keep their names.</p><h3 id="if-you-used-allowcustomvalue" tabindex="-1">If you used <code>allowCustomValue</code> <a class="header-anchor" href="#if-you-used-allowcustomvalue" aria-label="Permalink to “If you used allowCustomValue”">​</a></h3><p><code>Combobox</code> had a prop that accepted the typed text as the value and drew a built-in <code>Create &quot;…&quot;</code> row. It is gone. It could not do anything a custom row cannot, and it hardcoded the row — no way to change the label, add an icon, or say when it appears.</p><p>Build the row instead. It commits on click and on Enter, because Enter picks the highlighted row:</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1i4ay4"> setup</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> value</span><span class="s_2ekfrt"> =</span><span class="s_indoxt"> ref</span><span class="s_13ahmt">(</span><span class="s_w1p9wo">&#39;&#39;</span><span class="s_13ahmt">)</span></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> people</span><span class="s_2ekfrt"> =</span><span class="s_indoxt"> ref</span><span class="s_13ahmt">([</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">John Doe</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">Jane Doe</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt">])</span></span>
<span class="line"></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> options</span><span class="s_2ekfrt"> =</span><span class="s_indoxt"> computed</span><span class="s_13ahmt">(()</span><span class="s_50ecpt"> =&gt;</span><span class="s_13ahmt"> [</span></span>
<span class="line"><span class="s_fjrnv8">  ...</span><span class="s_22m8k2">people</span><span class="s_1jjt6x">.</span><span class="s_11933w">value</span><span class="s_1jjt6x">.</span><span class="s_indoxt">map</span><span class="s_13ahmt">((</span><span class="s_fsg3al">p</span><span class="s_13ahmt">)</span><span class="s_50ecpt"> =&gt;</span><span class="s_13ahmt"> ({</span><span class="s_r4oegk"> label</span><span class="s_1jjt6x">:</span><span class="s_11933w"> p</span><span class="s_1jjt6x">,</span><span class="s_r4oegk"> value</span><span class="s_1jjt6x">:</span><span class="s_11933w"> p</span><span class="s_13ahmt"> }))</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">  {</span></span>
<span class="line"><span class="s_r4oegk">    type</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">custom</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">    key</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">create</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">    label</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">Create</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">    slot</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">create</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_indoxt">    condition</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> (</span><span class="s_1jjt6x">{</span><span class="s_fsg3al"> query</span><span class="s_1jjt6x"> }</span><span class="s_13ahmt">)</span><span class="s_50ecpt"> =&gt;</span></span>
<span class="line"><span class="s_indoxt">      Boolean</span><span class="s_13ahmt">(</span><span class="s_22m8k2">query</span><span class="s_1jjt6x">.</span><span class="s_indoxt">trim</span><span class="s_13ahmt">())</span><span class="s_50ecpt"> &amp;&amp;</span><span class="s_50ecpt"> !</span><span class="s_22m8k2">people</span><span class="s_1jjt6x">.</span><span class="s_11933w">value</span><span class="s_1jjt6x">.</span><span class="s_indoxt">includes</span><span class="s_13ahmt">(</span><span class="s_22m8k2">query</span><span class="s_1jjt6x">.</span><span class="s_indoxt">trim</span><span class="s_13ahmt">())</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_indoxt">    onClick</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> (</span><span class="s_1jjt6x">{</span><span class="s_fsg3al"> query</span><span class="s_1jjt6x"> }</span><span class="s_13ahmt">)</span><span class="s_50ecpt"> =&gt;</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_22m8k2">      value</span><span class="s_1jjt6x">.</span><span class="s_11933w">value</span><span class="s_2ekfrt"> =</span><span class="s_22m8k2"> query</span><span class="s_1jjt6x">.</span><span class="s_indoxt">trim</span><span class="s_13ahmt">()</span></span>
<span class="line"><span class="s_13ahmt">    }</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">  }</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">])</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">template</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">  &lt;</span><span class="s_wac0bt">Combobox</span><span class="s_1i4ay4"> v-model</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">value</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> :options</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">options</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">    &lt;</span><span class="s_1uuh8p">template</span><span class="s_1jjt6x"> #</span><span class="s_1i4ay4">item-create</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_13ahmt">{</span><span class="s_22m8k2"> query</span><span class="s_13ahmt"> }</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span><span class="s_6am9cx">Create &quot;{{ query }}&quot;</span><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">template</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">  &lt;/</span><span class="s_wac0bt">Combobox</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">template</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p>A <code>modelValue</code> that matches no option is kept regardless — the trigger falls back to the raw string — so nothing else changes.</p><p><code>dialog.prompt</code>&#39;s <code>allowCreate</code> field option is unaffected; it now builds this row internally.</p><h3 id="if-you-filter-on-the-server" tabindex="-1">If you filter on the server <a class="header-anchor" href="#if-you-filter-on-the-server" aria-label="Permalink to “If you filter on the server”">​</a></h3><p><code>Combobox</code> and <code>MultiSelect</code> filter their options in the browser by default. When the options already come back from a search endpoint, that filters them a second time and drops fuzzy, ranked, or id-based matches. Pass <code>:filterable=&quot;false&quot;</code> to turn it off. Apps that forked the component for this reason can move back.</p><p>For the removed <code>Autocomplete</code>, see <a href="#autocomplete-removed">Autocomplete (removed)</a>.</p><h2 id="popover-hovercard-tooltip" tabindex="-1">Popover / HoverCard / Tooltip <a class="header-anchor" href="#popover-hovercard-tooltip" aria-label="Permalink to “Popover / HoverCard / Tooltip”">​</a></h2><p>The v0 <code>Popover</code> API is <strong>removed</strong> in <code>1.0.0</code>. Nothing is aliased and nothing warns — Vue drops an unknown prop or slot without complaining, so a missed call site renders a popover with no trigger, or an empty one. Check every <code>&lt;Popover&gt;</code> in your app.</p><table tabindex="0"><thead><tr><th>Before</th><th>After</th></tr></thead><tbody><tr><td><code>#target</code> slot</td><td><code>#trigger</code> — reka wires the click, so drop your own click handler</td></tr><tr><td><code>#body</code> slot</td><td><code>#default</code> + <code>bare</code> prop (renders without the panel shell)</td></tr><tr><td><code>#body-main</code> slot</td><td><code>#default</code></td></tr><tr><td><code>togglePopover</code> / <code>updatePosition</code> slot props</td><td><code>toggle</code> (<code>updatePosition</code> is gone — reka repositions on its own)</td></tr><tr><td><code>placement=&quot;bottom-start&quot;</code></td><td><code>side=&quot;bottom&quot;</code> + <code>align=&quot;start&quot;</code> (a bare side like <code>placement=&quot;bottom&quot;</code> maps to <code>align=&quot;center&quot;</code>)</td></tr><tr><td><code>show</code> / <code>v-model:show</code></td><td><code>open</code> / <code>v-model:open</code></td></tr><tr><td><code>update:show</code> emit</td><td><code>update:open</code></td></tr><tr><td><code>hideOnBlur</code></td><td><code>dismissible</code></td></tr><tr><td><code>matchTargetWidth</code></td><td><code>matchTriggerWidth</code></td></tr><tr><td><code>trigger=&quot;hover&quot;</code> (+ <code>hoverDelay</code> / <code>leaveDelay</code>)</td><td>the <a href="./components/hovercard"><code>HoverCard</code></a> component</td></tr><tr><td><code>popoverClass</code></td><td><code>data-slot</code> CSS hooks</td></tr><tr><td><code>transition=&quot;default&quot;</code></td><td>built-in motion — delete the prop</td></tr><tr><td><code>PopoverPlacement</code> type</td><td><code>PopoverSide</code> + <code>PopoverAlign</code></td></tr><tr><td><code>PopoverLegacySlotProps</code> type</td><td><code>PopoverSlotProps</code></td></tr><tr><td><code>NestedPopover</code></td><td><code>Popover</code> — <strong>loud</strong>: the import fails, so the build names every call site. It never nested, and it was the last <code>@popperjs/core</code> consumer</td></tr></tbody></table><p>Two more changes have no prop to grep for. v0 always set the panel&#39;s <code>min-width</code> to the trigger&#39;s width; v1 does it only under <code>matchTriggerWidth</code>, so a panel that leaned on that now shrinks to its content. And the panel no longer teleports into a <code>#frappeui-popper-root</code> div — reka portals it to <code>body</code>, or to the host&#39;s portal target. Delete any CSS or <code>document.querySelector</code> aimed at that id; nothing creates it now.</p><h3 id="trigger-and-content-slots" tabindex="-1">Trigger and content slots <a class="header-anchor" href="#trigger-and-content-slots" aria-label="Permalink to “Trigger and content slots”">​</a></h3><p><code>#target</code> did not wire anything — you called <code>togglePopover</code> yourself. <code>#trigger</code> renders through reka&#39;s <code>PopoverTrigger</code> as-child, which brings the click handler, keyboard support and <code>aria-expanded</code> with it. <strong>Keeping your click handler makes the popover toggle twice and stay shut.</strong></p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Popover</span><span class="s_1i4ay4"> placement</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">bottom-end</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;template #target=&quot;{ togglePopover }&quot;&gt;</span></span>
<span class="line"><span class="s_6am9cx">    &lt;Button label=&quot;Filter&quot; @click=&quot;togglePopover&quot; /&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;/template&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;template #body-main=&quot;{ close }&quot;&gt;</span></span>
<span class="line"><span class="s_6am9cx">    &lt;FilterPanel @done=&quot;close&quot; /&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;/template&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">Popover</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Popover</span><span class="s_1i4ay4"> side</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">bottom</span><span class="s_w1p9wo">&quot;</span><span class="s_suc1p8"> align</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">end</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;template #trigger&gt;</span></span>
<span class="line"><span class="s_6am9cx">    &lt;Button label=&quot;Filter&quot; /&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;/template&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;template #default=&quot;{ close }&quot;&gt;</span></span>
<span class="line"><span class="s_6am9cx">    &lt;FilterPanel @done=&quot;close&quot; /&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;/template&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">Popover</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p><code>#body</code> rendered outside the panel shell, so it maps to <code>#default</code> <strong>plus</strong><code>bare</code> — without <code>bare</code> your content ends up inside a second panel.</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Popover</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;template #body&gt;&lt;EmojiPicker /&gt;&lt;/template&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">Popover</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Popover</span><span class="s_1i4ay4"> bare</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;EmojiPicker /&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">Popover</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><h3 id="driving-the-popover-yourself" tabindex="-1">Driving the popover yourself <a class="header-anchor" href="#driving-the-popover-yourself" aria-label="Permalink to “Driving the popover yourself”">​</a></h3><p>If your trigger needs custom timing (a delayed open, a drag that must not open it), bind <code>open</code> and accept only closes, so the trigger&#39;s own toggle cannot open it behind your back:</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Popover</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">open</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">isOpen</span><span class="s_w1p9wo">&quot;</span><span class="s_1jjt6x"> @</span><span class="s_1i4ay4">update</span><span class="s_1jjt6x">:</span><span class="s_1i4ay4">open</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_13ahmt">(</span><span class="s_fsg3al">value</span><span class="s_13ahmt">)</span><span class="s_50ecpt"> =&gt;</span><span class="s_50ecpt"> !</span><span class="s_22m8k2">value</span><span class="s_50ecpt"> &amp;&amp;</span><span class="s_13ahmt"> (</span><span class="s_22m8k2">isOpen</span><span class="s_2ekfrt"> =</span><span class="s_40mev6"> false</span><span class="s_13ahmt">)</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;template #trigger&gt;</span></span>
<span class="line"><span class="s_6am9cx">    &lt;div @click=&quot;onClick&quot;&gt;…&lt;/div&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;/template&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">Popover</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><h3 id="slot-props" tabindex="-1">Slot props <a class="header-anchor" href="#slot-props" aria-label="Permalink to “Slot props”">​</a></h3><p><code>#trigger</code> and <code>#default</code> receive <code>{ open, close, toggle }</code>.</p><table tabindex="0"><thead><tr><th>Before</th><th>After</th></tr></thead><tbody><tr><td><code>isOpen</code></td><td><code>open</code></td></tr><tr><td><code>open</code> (a method to call)</td><td><code>toggle</code>, or nothing — see below</td></tr><tr><td><code>togglePopover</code></td><td><code>toggle</code></td></tr><tr><td><code>updatePosition</code></td><td>gone; reka repositions on its own</td></tr></tbody></table><p><code>open</code> is now the boolean state, which is what it already means on <code>Dropdown</code>, <code>Select</code>, <code>MultiSelect</code>, <code>HoverCard</code> and <code>Sidebar</code>. It used to be a method on <code>Popover</code> alone.</p><p>This one is silent and worth grepping for: a destructured <code>isOpen</code> becomes <code>undefined</code>, so a class bound to it stops applying with no error.</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">template</span><span class="s_1jjt6x"> #</span><span class="s_1i4ay4">trigger</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_13ahmt">{</span><span class="s_22m8k2"> isOpen</span><span class="s_13ahmt"> }</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">  &lt;</span><span class="s_1uuh8p">Button</span><span class="s_1i4ay4"> :class</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">isOpen &amp;&amp; &#39;ring-2&#39;</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> label</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">Filter</span><span class="s_w1p9wo">&quot;</span><span class="s_28rvie"> /</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">template</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">template</span><span class="s_1jjt6x"> #</span><span class="s_1i4ay4">trigger</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_13ahmt">{</span><span class="s_22m8k2"> open</span><span class="s_13ahmt"> }</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">  &lt;</span><span class="s_1uuh8p">Button</span><span class="s_1i4ay4"> :class</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">open &amp;&amp; &#39;ring-2&#39;</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> label</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">Filter</span><span class="s_w1p9wo">&quot;</span><span class="s_28rvie"> /</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">template</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p>Most triggers need nothing at all — <code>#trigger</code> wires its own click, so the <code>open()</code> method it used to hand out had no callers. <code>toggle</code> is there for the cases that drive it by hand.</p><h3 id="attributes-are-not-inherited" tabindex="-1">Attributes are not inherited <a class="header-anchor" href="#attributes-are-not-inherited" aria-label="Permalink to “Attributes are not inherited”">​</a></h3><p><code>&lt;Popover class=&quot;…&quot;&gt;</code> and <code>&lt;Popover :style=&quot;…&quot;&gt;</code> used to land on a wrapper the legacy <code>#target</code> rendered. <code>#trigger</code> is as-child and renders no wrapper, so those attributes now go nowhere. Move them onto the element inside <code>#trigger</code>.</p><h3 id="hover-panels" tabindex="-1">Hover panels <a class="header-anchor" href="#hover-panels" aria-label="Permalink to “Hover panels”">​</a></h3><p>Hover-driven panels move to the <a href="./components/hovercard"><code>HoverCard</code></a> component, which keeps <code>hoverDelay</code> / <code>leaveDelay</code> in seconds.</p><h3 id="tooltip" tabindex="-1">Tooltip <a class="header-anchor" href="#tooltip" aria-label="Permalink to “Tooltip”">​</a></h3><table tabindex="0"><thead><tr><th>Before</th><th>After</th></tr></thead><tbody><tr><td><code>placement=&quot;right&quot;</code></td><td><code>side=&quot;right&quot;</code></td></tr><tr><td><code>arrowClass</code></td><td><code>[data-slot=&quot;arrow&quot;]</code> CSS, or <code>offset</code> to shift the bubble</td></tr><tr><td><code>#body</code></td><td><code>#content</code> (add <code>bare</code> if the content owns its surface)</td></tr></tbody></table><p>All three are silent — the tooltip keeps working, it just points the wrong way, loses the styling, or comes up empty. <code>arrowClass</code> was documented as the arrow&#39;s fill, but was mostly used to nudge the bubble&#39;s position; <code>offset</code> does that directly.</p><p><code>#default</code> is still the <strong>trigger</strong>. That is deliberate and is not changing.</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Tooltip</span><span class="s_1i4ay4"> text</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">Preview</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> placement</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">bottom</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> arrow-class</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">mb-3</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;Button label=&quot;Preview&quot; /&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">Tooltip</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Tooltip</span><span class="s_1i4ay4"> text</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">Preview</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> side</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">bottom</span><span class="s_w1p9wo">&quot;</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">offset</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_40mev6">12</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;Button label=&quot;Preview&quot; /&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">Tooltip</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p><code>#body</code> replaced the whole bubble, surface included, so call sites hand-copied the bubble&#39;s own classes to get them back. <code>#content</code> renders inside the bubble, so that wrapper goes away:</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Tooltip</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;template #body&gt;</span></span>
<span class="line"><span class="s_6am9cx">    &lt;div</span></span>
<span class="line"><span class="s_6am9cx">      class=&quot;rounded bg-surface-gray-10 px-2 py-1 text-xs text-ink-base shadow-xl&quot;</span></span>
<span class="line"><span class="s_6am9cx">    &gt;</span></span>
<span class="line"><span class="s_6am9cx">      &lt;span&gt;Hide password&lt;/span&gt;</span></span>
<span class="line"><span class="s_6am9cx">    &lt;/div&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;/template&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;Button icon=&quot;eye&quot; /&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">Tooltip</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Tooltip</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;template #content&gt;</span></span>
<span class="line"><span class="s_6am9cx">    &lt;span&gt;Hide password&lt;/span&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;/template&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;Button icon=&quot;eye&quot; /&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">Tooltip</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p>If the content really does bring its own surface — an image preview, say — keep it and add <code>bare</code>:</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Tooltip</span><span class="s_1i4ay4"> bare</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;template #content&gt;</span></span>
<span class="line"><span class="s_6am9cx">    &lt;img :src=&quot;url&quot; class=&quot;max-h-40 rounded-4 shadow-xl&quot; /&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;/template&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;span class=&quot;truncate&quot;&gt;{{ filename }}&lt;/span&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">Tooltip</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><h2 id="inputs" tabindex="-1">Inputs <a class="header-anchor" href="#inputs" aria-label="Permalink to “Inputs”">​</a></h2><p>Covers <code>TextInput</code>, <code>Textarea</code>, <code>Password</code>, <code>Checkbox</code>, <code>Switch</code>, <code>Rating</code>, <code>Slider</code>. All share the labeling contract (<code>label</code> / <code>description</code> / <code>error</code> / <code>required</code>).</p><table tabindex="0"><thead><tr><th>Before</th><th>After</th></tr></thead><tbody><tr><td><code>&lt;Input&gt;</code> (removed)</td><td><code>TextInput</code> / <code>Textarea</code> / <code>Select</code> / <code>Checkbox</code>, or <code>FormControl</code></td></tr><tr><td><code>Rating</code> <code>:rating_from</code></td><td><code>:max</code></td></tr><tr><td><code>Rating</code> <code>:readonly</code></td><td><code>:disabled</code></td></tr><tr><td><code>Switch</code> <code>@change</code></td><td><code>@update:modelValue</code></td></tr><tr><td><code>Switch.labelClasses</code></td><td><code>data-*</code> styling hooks</td></tr><tr><td><code>Checkbox.padding</code></td><td><code>padded</code></td></tr><tr><td><code>Password</code> <code>:value</code> prop (removed)</td><td><code>v-model</code></td></tr><tr><td><code>TextInput</code> / <code>Textarea</code> ref <code>.el</code></td><td>ref <code>.inputElement</code></td></tr></tbody></table><p>The five rows below <code>&lt;Input&gt;</code> are <strong>removed</strong>, not aliased. The old names are silently ignored: a <code>Rating</code> with <code>:rating_from=&quot;10&quot;</code> renders 5 stars, a <code>:readonly</code> Rating becomes interactive, a <code>Switch</code> <code>@change</code> handler never fires, and <code>labelClasses</code> / <code>Checkbox.padding</code> stop styling anything. Nothing breaks at build time, so grep for these names when upgrading.</p><p><code>&lt;Input&gt;</code> is different: the import fails, so importing call sites break loudly. Apps that register components globally get no import error — the tag just fails to resolve and renders nothing, with a dev-only &quot;Failed to resolve component&quot; warning. Grep the tag, not the import: <code>grep -rn &#39;&lt;Input\\b&#39; src</code>.</p><p><code>Slider</code> no longer hardcodes <code>aria-label=&quot;Volume&quot;</code>. Pass <code>label</code> explicitly so the control is announced correctly.</p><p><code>CircularProgressBar</code> is deleted — the import fails. Use <code>Progress</code> for a linear bar, or render the arc yourself; there is no circular variant in v1.</p><h3 id="password-—-value-prop-removed" tabindex="-1">Password — <code>value</code> prop removed <a class="header-anchor" href="#password-—-value-prop-removed" aria-label="Permalink to “Password — value prop removed”">​</a></h3><p><code>value</code> was a deprecated alternate way to set the password, seeding <code>v-model</code> on mount. It&#39;s gone. <code>:value</code> now falls through as a plain HTML attribute on the native <code>&lt;input&gt;</code> instead of seeding the model — the field still renders, so nothing throws or warns.</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Password</span><span class="s_1i4ay4"> v-model</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">password</span><span class="s_w1p9wo">&quot;</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">value</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">initialValue</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Password</span><span class="s_1i4ay4"> v-model</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">password</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1i4ay4"> setup</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_22m8k2">password</span><span class="s_1jjt6x">.</span><span class="s_11933w">value</span><span class="s_2ekfrt"> =</span><span class="s_22m8k2"> initialValue</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><h3 id="textinput-textarea-password-—-ref-surface" tabindex="-1"><code>TextInput</code>, <code>Textarea</code>, <code>Password</code> — ref surface <a class="header-anchor" href="#textinput-textarea-password-—-ref-surface" aria-label="Permalink to “TextInput, Textarea, Password — ref surface”">​</a></h3><p><code>TextInput</code> and <code>Textarea</code> handed back <code>{ el }</code>, a raw ref on the native element. It&#39;s now <code>{ focus, inputElement }</code>: call <code>focus(options?)</code> to move keyboard focus, and read <code>inputElement</code> for the native element itself (a computed, so it can&#39;t be reassigned). <code>Password</code> gains the same pair — it previously exposed nothing.</p><p>This fails late rather than at build time: <code>ref.value.el</code> is <code>undefined</code>, so the next access — <code>ref.value.el.focus()</code> — throws at runtime, far from the upgrade. A typed ref catches it as a build error instead.</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">TextInput</span><span class="s_1i4ay4"> ref</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">input</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1i4ay4"> setup</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_50ecpt">function</span><span class="s_indoxt"> focusIt</span><span class="s_13ahmt">()</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_22m8k2">  input</span><span class="s_1jjt6x">.</span><span class="s_11933w">value</span><span class="s_1jjt6x">.</span><span class="s_11933w">el</span><span class="s_1jjt6x">.</span><span class="s_indoxt">focus</span><span class="s_13ahmt">({ </span><span class="s_r4oegk">preventScroll</span><span class="s_1jjt6x">:</span><span class="s_40mev6"> true</span><span class="s_13ahmt"> })</span></span>
<span class="line"><span class="s_13ahmt">}</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">TextInput</span><span class="s_1i4ay4"> ref</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">input</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1i4ay4"> setup</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_50ecpt">function</span><span class="s_indoxt"> focusIt</span><span class="s_13ahmt">()</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_22m8k2">  input</span><span class="s_1jjt6x">.</span><span class="s_11933w">value</span><span class="s_1jjt6x">.</span><span class="s_indoxt">focus</span><span class="s_13ahmt">({ </span><span class="s_r4oegk">preventScroll</span><span class="s_1jjt6x">:</span><span class="s_40mev6"> true</span><span class="s_13ahmt"> })</span></span>
<span class="line"><span class="s_13ahmt">}</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p><code>Duration</code> already exposed <code>focus()</code>; it now takes the same <code>options?</code> parameter as the rest of the family.</p><h2 id="fileuploader" tabindex="-1">FileUploader <a class="header-anchor" href="#fileuploader" aria-label="Permalink to “FileUploader”">​</a></h2><p><code>FileUploader</code> reached structural bar in <code>1.0.0</code>: TypeScript, flat props, and a security fix to the default it shares with <code>useFileUpload</code> / <code>FileUploadHandler</code>.</p><h3 id="uploads-default-to-private" tabindex="-1">Uploads default to private <a class="header-anchor" href="#uploads-default-to-private" aria-label="Permalink to “Uploads default to private”">​</a></h3><p><code>useFileUpload()</code> and <code>FileUploadHandler</code> now resolve an upload with no stated <code>private</code> / <code>is_private</code> to <strong>private</strong>, not public. Coming from v0, <code>FileUploader</code> flips with them: it had no <code>private</code> prop at all and inherited the public default. It has uploaded private by default since <code>v1.0.0-beta.21</code>, so only pre-beta.21 upgrades see the component change.</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">// Same call, before and after — the result changes:</span></span>
<span class="line"><span class="s_29n2kq">await</span><span class="s_indoxt"> useFileUpload</span><span class="s_13ahmt">()</span><span class="s_1jjt6x">.</span><span class="s_indoxt">upload</span><span class="s_13ahmt">(</span><span class="s_22m8k2">file</span><span class="s_1jjt6x">,</span><span class="s_13ahmt"> {})</span></span>
<span class="line"><span class="s_29n2kq">await</span><span class="s_2ekfrt"> new</span><span class="s_indoxt"> FileUploadHandler</span><span class="s_13ahmt">()</span><span class="s_1jjt6x">.</span><span class="s_indoxt">upload</span><span class="s_13ahmt">(</span><span class="s_22m8k2">file</span><span class="s_1jjt6x">,</span><span class="s_13ahmt"> {})</span></span>
<span class="line"><span class="s_1th9sy">// Before: is_private=0 (public).  After: is_private=1 (private).</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">// State the intent explicitly instead of relying on the default:</span></span>
<span class="line"><span class="s_29n2kq">await</span><span class="s_indoxt"> useFileUpload</span><span class="s_13ahmt">()</span><span class="s_1jjt6x">.</span><span class="s_indoxt">upload</span><span class="s_13ahmt">(</span><span class="s_22m8k2">file</span><span class="s_1jjt6x">,</span><span class="s_13ahmt"> {</span><span class="s_r4oegk"> private</span><span class="s_1jjt6x">:</span><span class="s_40mev6"> false</span><span class="s_13ahmt"> })</span><span class="s_1th9sy"> // public</span></span>
<span class="line"><span class="s_29n2kq">await</span><span class="s_indoxt"> useFileUpload</span><span class="s_13ahmt">()</span><span class="s_1jjt6x">.</span><span class="s_indoxt">upload</span><span class="s_13ahmt">(</span><span class="s_22m8k2">file</span><span class="s_1jjt6x">,</span><span class="s_13ahmt"> {</span><span class="s_r4oegk"> private</span><span class="s_1jjt6x">:</span><span class="s_40mev6"> true</span><span class="s_13ahmt"> })</span><span class="s_1th9sy"> // private</span></span></code></pre></div><p>If your app serves an uploaded file with no session — an avatar in an email digest, an image embedded on a public page — audit every call that omits <code>private</code> / <code>is_private</code> before upgrading. A file that flips to private returns <code>403</code> to a session-less request instead of the image.</p><h3 id="uploadargs-→-flat-props" tabindex="-1"><code>uploadArgs</code> → flat props <a class="header-anchor" href="#uploadargs-→-flat-props" aria-label="Permalink to “uploadArgs → flat props”">​</a></h3><p>The single <code>uploadArgs</code> object prop is gone. Its commonly-used fields are now flat props on the component:</p><table tabindex="0"><thead><tr><th>Before (<code>uploadArgs</code>)</th><th>After</th></tr></thead><tbody><tr><td><code>private</code> / <code>is_private</code></td><td><code>private</code></td></tr><tr><td><code>folder</code></td><td><code>folder</code></td></tr><tr><td><code>doctype</code></td><td><code>doctype</code></td></tr><tr><td><code>docname</code></td><td><code>docname</code></td></tr><tr><td><code>fieldname</code></td><td><code>fieldname</code></td></tr><tr><td><code>upload_endpoint</code></td><td><code>uploadEndpoint</code></td></tr><tr><td><code>optimize</code></td><td><code>optimize</code></td></tr></tbody></table><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">FileUploader</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">uploadArgs</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_13ahmt">{</span><span class="s_r4oegk"> private</span><span class="s_1jjt6x">: </span><span class="s_40mev6">false</span><span class="s_1jjt6x">, </span><span class="s_r4oegk">folder</span><span class="s_1jjt6x">: </span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">Attachments</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> }</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">FileUploader</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">private</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_40mev6">false</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> folder</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">Attachments</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span></code></pre></div><p>This is silent: <code>uploadArgs</code> isn&#39;t a recognized prop anymore, so Vue passes it through as an inert HTML attribute on the root element. Nothing throws — the options it carried just stop applying, and (combined with the default flip above) a <code>uploadArgs=&quot;{ private: false }&quot;</code> override that used to make an upload public silently starts uploading private instead. <code>grep</code> every <code>&lt;FileUploader&gt;</code> for <code>uploadArgs=</code> / <code>:upload-args=</code> and move each field to its flat prop.</p><p><code>file_url</code>, <code>method</code>, <code>type</code>, <code>params</code>, <code>max_width</code> / <code>max_height</code>, and upload cancellation (<code>signal</code>) have no flat-prop equivalent — they had no measured use on the component. Use <a href="./other/utilities#usefileupload-fileuploadhandler"><code>useFileUpload()</code></a> directly for those.</p><h3 id="template-ref-—-inputref-removed" tabindex="-1">Template ref — <code>inputRef</code> removed <a class="header-anchor" href="#template-ref-—-inputref-removed" aria-label="Permalink to “Template ref — inputRef removed”">​</a></h3><p><code>FileUploader</code> hands back nothing through a template ref, per <a href="https://github.com/frappe/frappe-ui/blob/main/spec/adr/0012-template-ref-surface.md" target="_blank" rel="noreferrer">ADR-0012</a>. <code>inputRef()</code> (a function, despite the name) is gone with nothing in its place — the <code>openFileSelector</code> slot prop already covers what it opened.</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">FileUploader</span><span class="s_1i4ay4"> ref</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">uploader</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1i4ay4"> setup</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_22m8k2">uploader</span><span class="s_1jjt6x">.</span><span class="s_11933w">value</span><span class="s_1jjt6x">.</span><span class="s_indoxt">inputRef</span><span class="s_13ahmt">()</span><span class="s_1jjt6x">.</span><span class="s_indoxt">click</span><span class="s_13ahmt">()</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">FileUploader</span><span class="s_1i4ay4"> v-slot</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_13ahmt">{</span><span class="s_22m8k2"> openFileSelector</span><span class="s_13ahmt"> }</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;Button @click=&quot;openFileSelector&quot;&gt;Upload&lt;/Button&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">FileUploader</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><h3 id="default-slot-s-error-prop-—-always-a-string" tabindex="-1">Default slot&#39;s <code>error</code> prop — always a string <a class="header-anchor" href="#default-slot-s-error-prop-—-always-a-string" aria-label="Permalink to “Default slot&#39;s error prop — always a string”">​</a></h3><p>The default slot&#39;s <code>error</code> prop is <code>string | null</code>, no longer <code>unknown</code>. Upload failures were always normalized to a message string; validation failures (a <code>validateFile</code> prop returning an <code>Error</code>) were not, so <code>error</code> could previously be an <code>Error</code> object too. Both paths normalize to a message string now.</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before: had to guard against error being a string or an Error --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">template</span><span class="s_1jjt6x"> #</span><span class="s_1i4ay4">default</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_13ahmt">{</span><span class="s_22m8k2"> error</span><span class="s_13ahmt"> }</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  {{ typeof error === &#39;string&#39; ? error : error?.message }}</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">template</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After: error is always a string --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">template</span><span class="s_1jjt6x"> #</span><span class="s_1i4ay4">default</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_13ahmt">{</span><span class="s_22m8k2"> error</span><span class="s_13ahmt"> }</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  {{ error }}</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">template</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p>This is silent: a slot that only ever did <code>error.message</code> (assuming the <code>Error</code> shape) now renders <code>undefined</code> instead of the validation message.</p><p><code>failure</code> also fires for validation now. A <code>validateFile</code> that returns a message or throws emits <code>failure</code> with that value; v0 only wrote it to the slot&#39;s <code>error</code>. An existing <code>@failure</code> handler starts seeing validation rejections alongside upload errors.</p><h3 id="filetobase64-and-the-size-limit-helpers-—-no-longer-exported" tabindex="-1"><code>fileToBase64</code> and the size-limit helpers — no longer exported <a class="header-anchor" href="#filetobase64-and-the-size-limit-helpers-—-no-longer-exported" aria-label="Permalink to “fileToBase64 and the size-limit helpers — no longer exported”">​</a></h3><p><code>fileToBase64</code> is no longer exported from <code>frappe-ui</code>; the import fails at build time. There were no external call sites at the v1 sweep. Computing a file&#39;s base64 representation yourself is a few lines of <code>FileReader.readAsDataURL</code>. The size-limit helpers (<code>formatBytes</code>, <code>getMaxFileSize</code>, <code>fileSizeLimitMessage</code>) were only ever exported during the <code>1.0.0</code> betas and are internal now.</p><h2 id="divider" tabindex="-1">Divider <a class="header-anchor" href="#divider" aria-label="Permalink to “Divider”">​</a></h2><table tabindex="0"><thead><tr><th>Before</th><th>After</th></tr></thead><tbody><tr><td><code>action.handler</code></td><td><code>action.onClick</code></td></tr></tbody></table><p>This is a <strong>silent break</strong>: <code>handler</code> is dropped as an unknown key, so the action button still renders and does nothing on click.</p><h2 id="listview-—-moved-to-frappe-ui-experimental" tabindex="-1">ListView — moved to <code>frappe-ui/experimental</code> <a class="header-anchor" href="#listview-—-moved-to-frappe-ui-experimental" aria-label="Permalink to “ListView — moved to frappe-ui/experimental”">​</a></h2><p><code>ListView</code> is not core v1 surface. It moves out of the root export to <code>frappe-ui/experimental</code> (P14 — no stability promise) and stays there until <code>frappe-ui/list</code> reaches full functional parity. The import fails at the root; switch the subpath:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">// Before</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">ListView</span><span class="s_1jjt6x">,</span><span class="s_4q1z3w"> ListRow</span><span class="s_1jjt6x">,</span><span class="s_4q1z3w"> ListHeader</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">// After</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">ListView</span><span class="s_1jjt6x">,</span><span class="s_4q1z3w"> ListRow</span><span class="s_1jjt6x">,</span><span class="s_4q1z3w"> ListHeader</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui/experimental</span><span class="s_w1p9wo">&#39;</span></span></code></pre></div><p>Every other name in the family moves the same way: <code>List</code>, <code>ListEmptyState</code>, <code>ListFooter</code>, <code>ListGroupHeader</code>, <code>ListGroupRows</code>, <code>ListGroups</code>, <code>ListHeaderItem</code>, <code>ListRowItem</code>, <code>ListRows</code>, <code>ListSelectBanner</code>. Nothing about the component itself changed — only where it&#39;s imported from.</p><h2 id="calendar-—-moved-to-frappe-ui-experimental" tabindex="-1">Calendar — moved to <code>frappe-ui/experimental</code> <a class="header-anchor" href="#calendar-—-moved-to-frappe-ui-experimental" aria-label="Permalink to “Calendar — moved to frappe-ui/experimental”">​</a></h2><p><code>Calendar</code> is not core v1 surface. It moves out of the root export to <code>frappe-ui/experimental</code> (P14 — no stability promise) and parks there, API unchanged, until a redesigned calendar family replaces it. The import fails at the root; switch the subpath:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">// Before</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">Calendar</span><span class="s_1jjt6x">,</span><span class="s_4q1z3w"> CalendarColorMap</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">// After</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">Calendar</span><span class="s_1jjt6x">,</span><span class="s_4q1z3w"> CalendarColorMap</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui/experimental</span><span class="s_w1p9wo">&#39;</span></span></code></pre></div><p>Every other name in the family moves the same way: <code>CalendarActiveEvent</code> and the types <code>CalendarActions</code>, <code>CalendarCellClickData</code>, <code>CalendarConfig</code>, <code>CalendarEvent</code>, <code>CalendarMode</code>, <code>CalendarPublicProps</code>, <code>CalendarTimeFormat</code>, <code>GroupedCalendarEvents</code>. Nothing about the component itself changed — only where it&#39;s imported from.</p><h2 id="charts-v1-—-moved-to-frappe-ui-experimental" tabindex="-1">Charts (v1) — moved to <code>frappe-ui/experimental</code> <a class="header-anchor" href="#charts-v1-—-moved-to-frappe-ui-experimental" aria-label="Permalink to “Charts (v1) — moved to frappe-ui/experimental”">​</a></h2><p>The first chart family is not core v1 surface. <code>AxisChart</code>, <code>DonutChart</code>, <code>ECharts</code>, <code>FunnelChart</code>, <code>NumberChart</code> and <code>useAxisChartOptions</code> move out of the root export to <code>frappe-ui/experimental</code> (P14 — no stability promise) and park there, API unchanged, while apps migrate. The import fails at the root; switch the subpath:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">// Before</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">AxisChart</span><span class="s_1jjt6x">,</span><span class="s_4q1z3w"> DonutChart</span><span class="s_1jjt6x">,</span><span class="s_4q1z3w"> NumberChart</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">// After</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">AxisChart</span><span class="s_1jjt6x">,</span><span class="s_4q1z3w"> DonutChart</span><span class="s_1jjt6x">,</span><span class="s_4q1z3w"> NumberChart</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui/experimental</span><span class="s_w1p9wo">&#39;</span></span></code></pre></div><p>Nothing about the components changed — only where they&#39;re imported from. Apps that spread <code>content</code> from <code>frappe-ui/tailwind</code> keep their styles automatically.</p><p>For new code, use <a href="/docs/charts/overview"><code>frappe-ui/charts</code></a> instead. It is the replacement family and draws everything the old one did. Its props are flat and name the columns of your rows, so a <code>config</code> object becomes props:</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">AxisChart</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">config</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_13ahmt">{</span><span class="s_r4oegk"> data</span><span class="s_1jjt6x">: </span><span class="s_22m8k2">rows</span><span class="s_1jjt6x">, </span><span class="s_r4oegk">xAxis</span><span class="s_1jjt6x">: </span><span class="s_13ahmt">{</span><span class="s_r4oegk"> key</span><span class="s_1jjt6x">: </span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">week</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> }</span><span class="s_1jjt6x">, </span><span class="s_r4oegk">series</span><span class="s_1jjt6x">: </span><span class="s_13ahmt">[{</span><span class="s_r4oegk"> name</span><span class="s_1jjt6x">: </span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">balance</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">, </span><span class="s_r4oegk">type</span><span class="s_1jjt6x">: </span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">area</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> }]</span><span class="s_13ahmt"> }</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">AreaChart</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">data</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">rows</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> x</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">week</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> y</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">balance</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span></code></pre></div><p>The port is not a pure rename. Four <code>config</code> keys have no same-named prop, so a rename-only port drops them <strong>silently</strong> — no build error, no type error, just a chart that scales or draws differently:</p><table tabindex="0"><thead><tr><th>v0 <code>config</code> key</th><th><code>frappe-ui/charts</code> prop</th></tr></thead><tbody><tr><td><code>yAxis.yMin</code> / <code>yAxis.yMax</code></td><td><code>yAxis.min</code> / <code>yAxis.max</code></td></tr><tr><td><code>y2Axis.yMin</code> / <code>y2Axis.yMax</code></td><td><code>y2Axis.min</code> / <code>y2Axis.max</code></td></tr><tr><td><code>swapXY</code></td><td><code>horizontal</code> (<code>BarChart</code> only — a horizontal bar has no <code>y2</code> axis)</td></tr><tr><td><code>colors</code></td><td><code>palette</code>, or <code>seriesConfig[key].color</code></td></tr></tbody></table><p>Combo charts survive the port: <code>seriesConfig[key].type</code> takes <code>&#39;bar&#39; | &#39;line&#39; | &#39;area&#39;</code>, and <code>seriesConfig[key].axis: &#39;y2&#39;</code> moves one series to the second value axis, configured with the chart-level <code>y2Axis</code> prop.</p><h2 id="sprite-icons-—-moved-to-frappe-ui-experimental" tabindex="-1">Sprite icons — moved to <code>frappe-ui/experimental</code> <a class="header-anchor" href="#sprite-icons-—-moved-to-frappe-ui-experimental" aria-label="Permalink to “Sprite icons — moved to frappe-ui/experimental”">​</a></h2><p>The sprite-based <code>Icon</code>, <code>IconPicker</code>, and <code>spritePlugin</code> are not core v1 surface. They move from <code>frappe-ui/icons</code> to <code>frappe-ui/experimental</code> (P14 — no stability promise). The old import fails; switch the subpath:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">// Before</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">Icon</span><span class="s_1jjt6x">,</span><span class="s_4q1z3w"> IconPicker</span><span class="s_1jjt6x">,</span><span class="s_4q1z3w"> spritePlugin</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui/icons</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">// After</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">Icon</span><span class="s_1jjt6x">,</span><span class="s_4q1z3w"> IconPicker</span><span class="s_1jjt6x">,</span><span class="s_4q1z3w"> spritePlugin</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui/experimental</span><span class="s_w1p9wo">&#39;</span></span></code></pre></div><p>Nothing about the components changed — only where they&#39;re imported from. Apps that spread <code>content</code> from <code>frappe-ui/tailwind</code> keep <code>IconPicker</code> styles automatically — no Tailwind change needed. Note that root <code>frappe-ui</code> exports a different <code>Icon</code>; alias one if you import both, e.g. <code>import { Icon as SpriteIcon } from &#39;frappe-ui/experimental&#39;</code>. The named SFC icons (<code>CircleCheckIcon</code>, <code>HelpIcon</code>, ...) stay on <code>frappe-ui/icons</code>. For new code, use <code>lucide-*</code> classes — they are the canonical way to render icons.</p><h2 id="alert" tabindex="-1">Alert <a class="header-anchor" href="#alert" aria-label="Permalink to “Alert”">​</a></h2><p><code>Alert</code> is stateless now — it has no <code>v-model</code> and never hides itself. The parent renders it with <code>v-if</code> and reacts to <code>@dismiss</code>. Layout is content-driven: a description or a second action switches it to the banner layout; there is no <code>variant</code> prop. See the <a href="./components/alert">Alert</a> component page for the full API.</p><table tabindex="0"><thead><tr><th>Before</th><th>After</th></tr></thead><tbody><tr><td>unnamed <code>v-model</code> (visibility)</td><td><code>v-if</code> + <code>@dismiss</code> — the parent owns hiding</td></tr><tr><td><code>theme=&quot;yellow&quot;</code></td><td><code>theme=&quot;amber&quot;</code></td></tr><tr><td><code>theme</code> default <code>&#39;blue&#39;</code></td><td>default <code>&#39;gray&#39;</code></td></tr><tr><td><code>variant=&quot;subtle&quot; / &quot;outline&quot;</code></td><td>nothing — one container look, layout is content-driven</td></tr><tr><td><code>type=&quot;warning&quot;</code></td><td>nothing — <code>theme</code> colors the status icon and the row action</td></tr><tr><td>default slot (body text)</td><td><code>description</code> prop, or the <code>#description</code> slot</td></tr><tr><td><code>dismissible</code> default <code>true</code></td><td>default <code>false</code> — pass <code>dismissible</code> to keep the ×</td></tr><tr><td><code>#icon</code> slot</td><td><code>#prefix</code> slot</td></tr><tr><td><code>#footer</code> slot</td><td><code>primaryAction</code> / <code>secondaryAction</code> props, or <code>#actions</code> slot</td></tr><tr><td>hand-rolled icon</td><td>the theme shows a status icon on its own; <code>:icon=&quot;false&quot;</code> opts out</td></tr></tbody></table><p>Every row is a <strong>silent break</strong>: Vue drops the unknown prop or slot with no error. The old <code>v-model</code> is the one to check first — a dismissed alert now stays on screen until the parent hides it:</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Alert</span><span class="s_1i4ay4"> v-model</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">showAlert</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> title</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">Payment failed</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> theme</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">yellow</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;template #footer&gt;</span></span>
<span class="line"><span class="s_6am9cx">    &lt;Button label=&quot;Retry&quot; @click=&quot;retry&quot; /&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;/template&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">Alert</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Alert</span></span>
<span class="line"><span class="s_50ecpt">  v-if</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">showAlert</span><span class="s_w1p9wo">&quot;</span></span>
<span class="line"><span class="s_1i4ay4">  title</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">Payment failed</span><span class="s_w1p9wo">&quot;</span></span>
<span class="line"><span class="s_1i4ay4">  theme</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">amber</span><span class="s_w1p9wo">&quot;</span></span>
<span class="line"><span class="s_1i4ay4">  dismissible</span></span>
<span class="line"><span class="s_1jjt6x">  :</span><span class="s_1i4ay4">primary-action</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_13ahmt">{</span><span class="s_r4oegk"> label</span><span class="s_1jjt6x">: </span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">Retry</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">, </span><span class="s_r4oegk">onClick</span><span class="s_1jjt6x">: </span><span class="s_22m8k2">retry</span><span class="s_13ahmt"> }</span><span class="s_w1p9wo">&quot;</span></span>
<span class="line"><span class="s_1jjt6x">  @</span><span class="s_1i4ay4">dismiss</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">showAlert</span><span class="s_2ekfrt"> =</span><span class="s_40mev6"> false</span><span class="s_w1p9wo">&quot;</span></span>
<span class="line"><span class="s_6am9cx">/&gt;</span></span></code></pre></div><p>An action is <code>ButtonProps</code> plus an <code>onClick</code> that receives <code>{ dismiss }</code> — call <code>context.dismiss()</code> to emit the alert&#39;s <code>dismiss</code> event:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> primaryAction</span><span class="s_2ekfrt"> =</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_r4oegk">  label</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">Retry</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_indoxt">  onClick</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> (</span><span class="s_1jjt6x">{</span><span class="s_fsg3al"> dismiss</span><span class="s_1jjt6x"> }</span><span class="s_13ahmt">)</span><span class="s_50ecpt"> =&gt;</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_indoxt">    retry</span><span class="s_13ahmt">()</span></span>
<span class="line"><span class="s_indoxt">    dismiss</span><span class="s_13ahmt">()</span></span>
<span class="line"><span class="s_13ahmt">  }</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">}</span></span></code></pre></div><p>If the alert was really a promotional card in a sidebar, use the new <a href="./components/sidebar"><code>SidebarCard</code></a> component instead.</p><h2 id="badge" tabindex="-1">Badge <a class="header-anchor" href="#badge" aria-label="Permalink to “Badge”">​</a></h2><p><code>theme=&quot;orange&quot;</code> is removed. It was a deprecated alias that resolved to <code>amber</code>, so the replacement renders the same badge it always did.</p><table tabindex="0"><thead><tr><th>Before</th><th>After</th></tr></thead><tbody><tr><td><code>theme=&quot;orange&quot;</code></td><td><code>theme=&quot;amber&quot;</code></td></tr></tbody></table><p>How the break shows up depends on whether the call site is typed:</p><ul><li><strong>TypeScript: loud.</strong> <code>vue-tsc</code> rejects the value, because the <code>theme</code> prop union no longer accepts the string. You get a compile error, not a surprise in production.</li><li><strong>JavaScript and bound values: silent.</strong> The badge renders in the default <code>gray</code> theme and logs a one-time dev-mode warning naming the component, the prop and the value. Production logs nothing.</li></ul><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_wvjl67">[frappe-ui] Badge.theme=&quot;orange&quot; is not a supported value — falling back to</span></span>
<span class="line"><span class="s_wvjl67">&quot;gray&quot;. Supported: gray, blue, green, amber, red, violet.</span></span></code></pre></div><p>A missed site is therefore a grey badge, not a broken page. <code>Badge</code> used to index a class map by theme and then index the result again by variant, so an unknown theme threw <code>TypeError: Cannot read properties of undefined</code> mid-render and took the parent render with it. All three of <code>theme</code>, <code>variant</code> and <code>size</code> now fall back to their defaults instead.</p><p>Do not rely on the fallback. It is a safety net for the upgrade, not a supported way to pass a colour — a grey badge where a coloured one belongs is still a bug, and the dev warning is the only thing that will tell you.</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Badge</span><span class="s_1i4ay4"> theme</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">orange</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> label</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">In Progress</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Badge</span><span class="s_1i4ay4"> theme</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">amber</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> label</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">In Progress</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span></code></pre></div><p>Check bound themes too, not only literal attributes. A status-to-theme map or a computed that returns <code>&#39;orange&#39;</code> degrades the same way, and neither <code>vue-tsc</code> nor a grep for <code>theme=&quot;orange&quot;</code> finds it:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">// Before</span></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> themeByStatus</span><span class="s_2ekfrt"> =</span><span class="s_13ahmt"> {</span><span class="s_r4oegk"> open</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">orange</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_r4oegk"> closed</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">green</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> }</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">// After</span></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> themeByStatus</span><span class="s_2ekfrt"> =</span><span class="s_13ahmt"> {</span><span class="s_r4oegk"> open</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">amber</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_r4oegk"> closed</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">green</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> }</span></span></code></pre></div><p>Watch for <code>orange</code> as a <strong>fallback</strong>, which affects more sites than it looks — every caller that omits a theme lands on it:</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before — every caller without \`badge.theme\` renders grey --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Badge</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">theme</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">badge</span><span class="s_1jjt6x">.</span><span class="s_11933w">theme</span><span class="s_50ecpt"> ??</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">orange</span><span class="s_w1p9wo">&#39;&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Badge</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">theme</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">badge</span><span class="s_1jjt6x">.</span><span class="s_11933w">theme</span><span class="s_50ecpt"> ??</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">amber</span><span class="s_w1p9wo">&#39;&quot;</span><span class="s_1zd9e2"> /&gt;</span></span></code></pre></div><p>If your app keeps its own colour vocabulary and cannot rename <code>orange</code> at the source, translate at the boundary instead of passing it through:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> badgeTheme</span><span class="s_2ekfrt"> =</span><span class="s_22m8k2"> tone</span><span class="s_50ecpt"> ===</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">orange</span><span class="s_w1p9wo">&#39;</span><span class="s_50ecpt"> ?</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">amber</span><span class="s_w1p9wo">&#39;</span><span class="s_50ecpt"> :</span><span class="s_22m8k2"> tone</span></span></code></pre></div><h2 id="sidebar" tabindex="-1">Sidebar <a class="header-anchor" href="#sidebar" aria-label="Permalink to “Sidebar”">​</a></h2><p><code>Sidebar</code> is a bare frame — compose <code>SidebarHeader</code> / <code>SidebarSection</code> / <code>SidebarLabel</code> / <code>SidebarItem</code> in its default slot instead of passing config-object props. See the <a href="./components/sidebar">Sidebar</a> component page for the full API.</p><table tabindex="0"><thead><tr><th>Before</th><th>After</th></tr></thead><tbody><tr><td><code>:header=&quot;{ title, subtitle, menuItems }&quot;</code></td><td><code>&lt;SidebarHeader :title :subtitle :menu-items /&gt;</code> as a child</td></tr><tr><td><code>:sections=&quot;[{ label, items }]&quot;</code></td><td><code>&lt;SidebarLabel&gt;</code> + <code>&lt;SidebarItem&gt;</code> (or <code>&lt;SidebarSection&gt;</code>) as children</td></tr><tr><td><code>&lt;template #header-logo&gt;</code></td><td><code>&lt;SidebarHeader&gt;</code>&#39;s <code>#prefix</code> slot</td></tr><tr><td><code>&lt;template #footer-items&gt;</code></td><td>plain markup in the default slot</td></tr><tr><td><code>&lt;SidebarSection :items=&quot;rows&quot;&gt;</code></td><td><code>&lt;SidebarSection&gt;</code> with <code>&lt;SidebarItem&gt;</code> children</td></tr><tr><td><code>&lt;template #sidebar-item=&quot;{ item }&quot;&gt;</code></td><td>write the <code>&lt;SidebarItem&gt;</code> directly, no slot needed</td></tr><tr><td><code>item.condition</code></td><td><code>v-if</code> on the composed <code>&lt;SidebarItem&gt;</code></td></tr><tr><td><code>SidebarItem.isActive</code></td><td><code>SidebarItem.active</code></td></tr><tr><td><code>SidebarHeader</code>&#39;s <code>#logo</code> slot</td><td><code>#prefix</code> slot</td></tr></tbody></table><p>Every removal here is a <strong>silent break</strong>. A dropped prop (<code>header</code>, <code>sections</code>, <code>items</code>, <code>isActive</code>) becomes a fall-through attribute on the component&#39;s root element, and content passed to the removed <code>#sidebar-item</code> slot is discarded — no build error, no type error, no warning. The sidebar renders as an empty frame. Grep for <code>:header=</code>, <code>:sections=</code>, <code>:items=</code>, <code>#sidebar-item</code> and <code>isActive</code> on these five components after upgrading.</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Sidebar</span></span>
<span class="line"><span class="s_1jjt6x">  :</span><span class="s_1i4ay4">header</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_13ahmt">{</span><span class="s_r4oegk"> title</span><span class="s_1jjt6x">: </span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">Frappe CRM</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">, </span><span class="s_r4oegk">subtitle</span><span class="s_1jjt6x">: </span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">crm.frappe.io</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">, </span><span class="s_22m8k2">menuItems</span><span class="s_13ahmt"> }</span><span class="s_w1p9wo">&quot;</span></span>
<span class="line"><span class="s_1jjt6x">  :</span><span class="s_1i4ay4">sections</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_13ahmt">[</span></span>
<span class="line"><span class="s_13ahmt">    {</span><span class="s_r4oegk"> label</span><span class="s_1jjt6x">: </span><span class="s_w1p9wo">&#39;&#39;</span><span class="s_1jjt6x">, </span><span class="s_r4oegk">items</span><span class="s_1jjt6x">: </span><span class="s_13ahmt">[{</span><span class="s_r4oegk"> label</span><span class="s_1jjt6x">: </span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">Leads</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">, </span><span class="s_r4oegk">to</span><span class="s_1jjt6x">: </span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">/leads</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">, </span><span class="s_r4oegk">icon</span><span class="s_1jjt6x">: </span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">lucide-user-plus</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> }]</span><span class="s_13ahmt"> }</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">    {</span><span class="s_r4oegk"> label</span><span class="s_1jjt6x">: </span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">Views</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">, </span><span class="s_r4oegk">collapsible</span><span class="s_1jjt6x">: </span><span class="s_40mev6">true</span><span class="s_1jjt6x">, </span><span class="s_r4oegk">items</span><span class="s_1jjt6x">: </span><span class="s_11933w">viewItems</span><span class="s_13ahmt"> }</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">  ]</span><span class="s_w1p9wo">&quot;</span></span>
<span class="line"><span class="s_6am9cx">/&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_6am9cx">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_6am9cx">&lt;Sidebar&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;SidebarHeader title=&quot;Frappe CRM&quot; subtitle=&quot;crm.frappe.io&quot; :menu-items=&quot;menuItems&quot; /&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;div class=&quot;flex-1 overflow-y-auto px-2&quot;&gt;</span></span>
<span class="line"><span class="s_6am9cx">    &lt;SidebarItem label=&quot;Leads&quot; to=&quot;/leads&quot; icon=&quot;lucide-user-plus&quot; /&gt;</span></span>
<span class="line"><span class="s_6am9cx">    &lt;SidebarSection label=&quot;Views&quot; collapsible&gt;</span></span>
<span class="line"><span class="s_6am9cx">      &lt;SidebarItem v-for=&quot;item in viewItems&quot; :key=&quot;item.label&quot; v-bind=&quot;item&quot; /&gt;</span></span>
<span class="line"><span class="s_6am9cx">    &lt;/SidebarSection&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;/div&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">Sidebar</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p><code>Sidebar</code> no longer wraps the middle list in a scroll container or applies any padding — that&#39;s app-owned now (see the component page&#39;s Collapse section for the full composition contract).</p><h2 id="settingsdialog" tabindex="-1">SettingsDialog <a class="header-anchor" href="#settingsdialog" aria-label="Permalink to “SettingsDialog”">​</a></h2><p>Open state moves from the unnamed <code>v-model</code> to <code>v-model:open</code>, the name every other overlay in the library uses.</p><p>This is a <strong>silent break</strong>: Vue accepts the unknown <code>modelValue</code> prop with no error, so the dialog just never opens.</p><table tabindex="0"><thead><tr><th>Before</th><th>After</th></tr></thead><tbody><tr><td><code>v-model=&quot;showSettings&quot;</code></td><td><code>v-model:open=&quot;showSettings&quot;</code></td></tr><tr><td><code>@update:modelValue=&quot;onToggle&quot;</code></td><td><code>@update:open=&quot;onToggle&quot;</code></td></tr></tbody></table><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">SettingsDialog</span><span class="s_1i4ay4"> v-model</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">showSettings</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> v-model</span><span class="s_1jjt6x">:</span><span class="s_1i4ay4">tab</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">tab</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span><span class="s_6am9cx">…</span><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">SettingsDialog</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">SettingsDialog</span><span class="s_1i4ay4"> v-model</span><span class="s_1jjt6x">:</span><span class="s_1i4ay4">open</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">showSettings</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> v-model</span><span class="s_1jjt6x">:</span><span class="s_1i4ay4">tab</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">tab</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span><span class="s_6am9cx">…</span><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">SettingsDialog</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p><code>v-model:tab</code> is unchanged. Unlike <code>Dialog</code>, <code>SettingsDialog</code> has no legacy unnamed-<code>v-model</code> binding to keep — <code>open</code> is the only visibility channel.</p><h2 id="tabs" tabindex="-1">Tabs <a class="header-anchor" href="#tabs" aria-label="Permalink to “Tabs”">​</a></h2><p>The monolithic <code>Tabs</code> is replaced by a composed family: <code>Tabs</code>, <code>TabList</code>, <code>TabTrigger</code>, <code>TabPanel</code>. The model is the trigger <code>value</code>, never an index. See the <a href="./components/tabs">Tabs</a> component page for the full API.</p><p>There is no codemod for the Tabs family. <code>tokens-v2</code> rewrites Tailwind token names only — it never touches a component, prop, or slot name. Every rename below is a hand edit, and most of them fail silently, so grep for the old name rather than waiting for the build to tell you.</p><table tabindex="0"><thead><tr><th>Before</th><th>After</th></tr></thead><tbody><tr><td><code>v-model=&quot;tabIndex&quot;</code> (index)</td><td><code>v-model=&quot;tab&quot;</code> (trigger <code>value</code>)</td></tr><tr><td><code>:tabs=&quot;[{ label, icon }]&quot;</code> (required)</td><td><code>&lt;TabTrigger&gt;</code> children; the <code>tabs</code> shorthand stays for generated sets</td></tr><tr><td><code>label</code> implied the value</td><td><code>value</code> is required on every trigger</td></tr><tr><td><code>as=&quot;div&quot;</code></td><td>removed — compose and style the container directly</td></tr><tr><td><code>&lt;template #tab-item=&quot;{ tab, selected }&quot;&gt;</code></td><td><code>TabTrigger</code> props (<code>icon</code>, <code>iconLeft</code>, <code>route</code>) and slots (<code>#prefix</code>, default, <code>#suffix</code>), or <code>#tab-label</code> in shorthand mode</td></tr><tr><td><code>#prefix</code> / <code>#label</code> / <code>#suffix</code> / <code>#panel</code> alongside <code>:tabs</code></td><td><code>#tab-prefix</code> / <code>#tab-label</code> / <code>#tab-suffix</code> / <code>#tab-panel</code> — every shorthand slot carries the <code>tab-</code> prefix; composed <code>TabTrigger</code> keeps plain <code>#prefix</code> / <code>#suffix</code>. An unknown slot name renders nothing, nothing throws</td></tr><tr><td>extra fields on a <code>tabs</code> item (<code>{ value, content }</code>)</td><td><code>data: { content }</code>, read as <code>tab.data.content</code> — extra keys are now a type error</td></tr><tr><td><code>&lt;template #tab-panel=&quot;{ tab }&quot;&gt;</code></td><td><code>&lt;TabPanel :value&gt;</code> children; the shorthand slot is <code>#tab-panel</code>, back on its v0 name (it was briefly <code>#panel</code> in the betas)</td></tr><tr><td><code>Tab.route</code> string + hand-rolled route sync</td><td><code>route: RouteLocationRaw</code> on the trigger; selection derives from the route</td></tr><tr><td>stale-index clamps for conditional tabs</td><td>built in: a stale model falls back to the first visible trigger and emits</td></tr><tr><td><code>[&amp;_[role=&#39;tablist&#39;]]:px-4</code> class blobs</td><td><code>&lt;TabList class=&quot;px-4&quot;&gt;</code> — the app owns the element</td></tr><tr><td>built-in flex and overflow defaults</td><td>none — see Scrolling below; the tabs stop scrolling and overflow instead</td></tr><tr><td><code>iconRight</code> on a trigger or a <code>tabs</code> item</td><td><code>&lt;template #suffix&gt;</code> on a composed <code>TabTrigger</code>, <code>&lt;template #tab-suffix&gt;</code> in shorthand mode — the icon silently stops rendering, nothing throws</td></tr></tbody></table><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Tabs</span><span class="s_1i4ay4"> v-model</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">tabIndex</span><span class="s_w1p9wo">&quot;</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">tabs</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_13ahmt">[{</span><span class="s_r4oegk"> label</span><span class="s_1jjt6x">: </span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">Emails</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> }</span><span class="s_1jjt6x">, </span><span class="s_13ahmt">{</span><span class="s_r4oegk"> label</span><span class="s_1jjt6x">: </span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">Calls</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> }]</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;template #tab-item=&quot;{ tab, selected }&quot;&gt;</span></span>
<span class="line"><span class="s_6am9cx">    &lt;span :class=&quot;selected ? &#39;text-ink-gray-9&#39; : &#39;&#39;&quot;&gt;{{ tab.label }}&lt;/span&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;/template&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;template #tab-panel=&quot;{ tab }&quot;&gt;</span></span>
<span class="line"><span class="s_6am9cx">    &lt;div&gt;{{ tab.label }} content&lt;/div&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;/template&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">Tabs</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Tabs</span><span class="s_1i4ay4"> v-model</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">tab</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;TabList&gt;</span></span>
<span class="line"><span class="s_6am9cx">    &lt;TabTrigger value=&quot;emails&quot; label=&quot;Emails&quot; /&gt;</span></span>
<span class="line"><span class="s_6am9cx">    &lt;TabTrigger value=&quot;calls&quot; label=&quot;Calls&quot; /&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;/TabList&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;TabPanel value=&quot;emails&quot;&gt;Emails content&lt;/TabPanel&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;TabPanel value=&quot;calls&quot;&gt;Calls content&lt;/TabPanel&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">Tabs</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p><code>Tabs</code> exposes nothing on the template ref, and <code>TabList</code> gains full variant parity with <code>TabButtons</code>: <code>underline</code>, <code>subtle</code>, <code>ghost</code>, <code>browser-tab</code>.</p><h3 id="scrolling" tabindex="-1">Scrolling <a class="header-anchor" href="#scrolling" aria-label="Permalink to “Scrolling”">​</a></h3><p>v0 shipped layout defaults: the root was <code>flex flex-1 overflow-hidden flex-col</code>, the tablist <code>overflow-x-auto</code>, and every panel <code>flex flex-col overflow-auto</code>. v1 sets none of them, because they broke as often as they helped — a <code>Tabs</code> that force-grows to fill its parent is wrong everywhere the tabs are not the whole screen.</p><p>Nothing throws. Inside a height-constrained container the panel stops scrolling and overflows instead. Check any call site that relied on it.</p><p>In composed mode the app owns the elements, so put the classes back where you want them:</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Tabs</span><span class="s_1i4ay4"> v-model</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">tab</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> class</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">flex min-h-0 flex-1 flex-col</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;TabList class=&quot;overflow-x-auto&quot;&gt;…&lt;/TabList&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;TabPanel value=&quot;emails&quot; class=&quot;min-h-0 flex-1 overflow-auto&quot;&gt;…&lt;/TabPanel&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">Tabs</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p>In shorthand mode the generated elements are not yours to class, so reach them through their <code>data-slot</code> hooks:</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Tabs</span></span>
<span class="line"><span class="s_1i4ay4">  v-model</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">tab</span><span class="s_w1p9wo">&quot;</span></span>
<span class="line"><span class="s_1jjt6x">  :</span><span class="s_1i4ay4">tabs</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">items</span><span class="s_w1p9wo">&quot;</span></span>
<span class="line"><span class="s_1i4ay4">  class</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">min-h-0 flex-1 [&amp;_[data-slot=tab-list]]:overflow-x-auto [&amp;_[data-slot=tab-panel]]:min-h-0 [&amp;_[data-slot=tab-panel]]:flex-1 [&amp;_[data-slot=tab-panel]]:overflow-auto</span><span class="s_w1p9wo">&quot;</span></span>
<span class="line"><span class="s_6am9cx">/&gt;</span></span></code></pre></div><h2 id="tabbuttons" tabindex="-1">TabButtons <a class="header-anchor" href="#tabbuttons" aria-label="Permalink to “TabButtons”">​</a></h2><p><code>TabButtons</code> keeps its radiogroup role — a value input, not a panel switcher — and aligns its vocabulary with the Tabs family. See the <a href="./components/tabbuttons">TabButtons</a> component page for the full API.</p><table tabindex="0"><thead><tr><th>Before</th><th>After</th></tr></thead><tbody><tr><td><code>type=&quot;ghost&quot;</code></td><td><code>variant=&quot;ghost&quot;</code></td></tr><tr><td><code>direction=&quot;right&quot;</code></td><td><code>side=&quot;right&quot;</code> — the same prop name on <code>TabList</code></td></tr><tr><td><code>TabButtonsType</code> / <code>TabButtonsDirection</code> types</td><td><code>TabsVariant</code> / <code>TabsSide</code>, shared with the Tabs family</td></tr><tr><td><code>:buttons=&quot;items&quot;</code> (deprecated)</td><td><code>:options=&quot;items&quot;</code></td></tr><tr><td><code>{ label: &#39;Day&#39; }</code> (label as value)</td><td><code>value</code> is required on every option</td></tr><tr><td><code>{ active: true }</code> fallback</td><td>the <code>v-model</code> is the single source of truth</td></tr><tr><td>boolean <code>value</code> / <code>modelValue</code></td><td><code>string | number</code> only</td></tr><tr><td>wrapper divs / raw CSS for equal-width tabs</td><td><code>fluid</code> prop</td></tr><tr><td><code>iconRight</code> on an option</td><td><code>&lt;template #suffix&gt;</code> — silent, nothing throws</td></tr><tr><td><code>hideLabel: true</code> on an option</td><td><code>icon</code> alone — the option is icon-only and <code>label</code> becomes its accessible name</td></tr><tr><td><code>theme</code> / <code>variant</code> / <code>size</code> / <code>loading</code> on an option</td><td>removed — options no longer forward <code>Button</code> props. Use <code>Button</code> directly for per-tab theming or a spinner</td></tr><tr><td><code>tooltip</code> on an option</td><td>still <code>tooltip</code>, but it renders as the native <code>title</code> attribute, not a floating <code>Tooltip</code></td></tr></tbody></table><p>Every prop rename here is a <strong>silent break</strong>: an unknown prop lands in <code>$attrs</code> and is spread onto the radiogroup root, so a <code>TabButtons</code> still on <code>:buttons</code> renders an empty track with no build error, type error, or warning. As with Tabs, there is no codemod — grep for <code>:buttons</code>, <code>type=</code>, <code>direction=</code> and <code>hideLabel</code>.</p><h2 id="data-fetching-usedoctype-uselist" tabindex="-1">Data fetching (useDoctype / useList) <a class="header-anchor" href="#data-fetching-usedoctype-uselist" aria-label="Permalink to “Data fetching (useDoctype / useList)”">​</a></h2><p>The write methods on <code>useDoctype</code> (<code>insert</code>, <code>delete</code>, <code>setValue</code>, <code>runDocMethod</code>, <code>runMethod</code>) and on <code>useList</code> (<code>insert</code>, <code>setValue</code>, <code>delete</code>) used to share one request between all their submits. Each one now sends its own request, so the shared-request members are gone.</p><p>Nothing fails to build, so grep for these by hand. There are two failure modes, and one of them is quiet. Calling a removed method throws (<code>delete.execute()</code>, <code>insert.reset()</code>), and so does dotting into one (<code>delete.params.name</code>). A removed <em>data</em> member reads as <code>undefined</code> instead: <code>runMethod.isFetching</code> is always falsy, so a spinner silently never shows and nothing says why.</p><table tabindex="0"><thead><tr><th>Before</th><th>After</th></tr></thead><tbody><tr><td><code>delete.loading &amp;&amp; delete.params.name === row.name</code></td><td><code>delete.isLoading(row.name)</code></td></tr><tr><td><code>setValue.params.name</code></td><td><code>setValue.isLoading(name)</code></td></tr><tr><td><code>delete.execute()</code> / <code>.fetch()</code> / <code>.reload()</code></td><td><code>delete.submit({ name })</code></td></tr><tr><td><code>insert.reset()</code> / <code>.abort()</code></td><td>removed, no replacement</td></tr><tr><td><code>runMethod.isFetching</code> / <code>.isFinished</code></td><td><code>runMethod.loading</code></td></tr><tr><td><code>setValue.promise</code></td><td><code>await setValue.submit(...)</code></td></tr><tr><td><code>delete.url</code></td><td>removed, no replacement</td></tr></tbody></table><p>All eight now have the same five members: <code>submit()</code>, <code>data</code>, <code>error</code>, <code>loading</code> and <code>isLoading()</code>.</p><p><code>isLoading()</code> takes whatever identifies one submit:</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_22m8k2">todos</span><span class="s_1jjt6x">.</span><span class="s_11933w">delete</span><span class="s_1jjt6x">.</span><span class="s_indoxt">isLoading</span><span class="s_13ahmt">(</span><span class="s_22m8k2">row</span><span class="s_1jjt6x">.</span><span class="s_11933w">name</span><span class="s_13ahmt">)</span></span>
<span class="line"><span class="s_22m8k2">todos</span><span class="s_1jjt6x">.</span><span class="s_11933w">setValue</span><span class="s_1jjt6x">.</span><span class="s_indoxt">isLoading</span><span class="s_13ahmt">(</span><span class="s_22m8k2">row</span><span class="s_1jjt6x">.</span><span class="s_11933w">name</span><span class="s_13ahmt">)</span></span>
<span class="line"><span class="s_22m8k2">todos</span><span class="s_1jjt6x">.</span><span class="s_11933w">runDocMethod</span><span class="s_1jjt6x">.</span><span class="s_indoxt">isLoading</span><span class="s_13ahmt">(</span><span class="s_22m8k2">row</span><span class="s_1jjt6x">.</span><span class="s_11933w">name</span><span class="s_1jjt6x">,</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">archive</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt">)</span></span>
<span class="line"><span class="s_22m8k2">todos</span><span class="s_1jjt6x">.</span><span class="s_11933w">runMethod</span><span class="s_1jjt6x">.</span><span class="s_indoxt">isLoading</span><span class="s_13ahmt">(</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">sync_all</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt">)</span></span>
<span class="line"><span class="s_22m8k2">todos</span><span class="s_1jjt6x">.</span><span class="s_11933w">insert</span><span class="s_1jjt6x">.</span><span class="s_indoxt">isLoading</span><span class="s_13ahmt">()</span><span class="s_1th9sy"> // no argument: a new row has no name yet</span></span></code></pre></div><p><code>insert.isLoading()</code> gives the same answer as <code>insert.loading</code>. It is there so every write method reads the same way.</p><p>More changes you will not see at build time:</p><ul><li><p><code>submit()</code> now resolves with its own response. Code that fired two submits and read the result of the first was receiving the second one&#39;s data, or <code>null</code>. If you queued submits to work around that, you can drop the queue.</p></li><li><p><code>data</code> and <code>error</code> belong to the submit that started last, not the one that answered last. A slow submit that comes back after a newer one writes nothing and clears nothing. It still answers its own caller with its own outcome — resolving with its response, or rejecting with its error.</p></li><li><p><strong><code>data</code> is no longer reset to <code>null</code> when a submit fails.</strong> It used to be, because the shared request cleared it on any not-ok response. It now keeps the last successful response.</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_29n2kq">await</span><span class="s_22m8k2"> todos</span><span class="s_1jjt6x">.</span><span class="s_11933w">setValue</span><span class="s_1jjt6x">.</span><span class="s_indoxt">submit</span><span class="s_13ahmt">({</span><span class="s_r4oegk"> name</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">TODO-1</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_r4oegk"> status</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">Done</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> })</span></span>
<span class="line"><span class="s_29n2kq">await</span><span class="s_22m8k2"> todos</span><span class="s_1jjt6x">.</span><span class="s_11933w">setValue</span><span class="s_1jjt6x">.</span><span class="s_indoxt">submit</span><span class="s_13ahmt">({</span><span class="s_r4oegk"> name</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">TODO-2</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_r4oegk"> status</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">Done</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> })</span><span class="s_1th9sy"> // fails</span></span>
<span class="line"></span>
<span class="line"><span class="s_22m8k2">todos</span><span class="s_1jjt6x">.</span><span class="s_22m8k2">setValue</span><span class="s_1jjt6x">.</span><span class="s_11933w">data</span><span class="s_1th9sy"> // still the TODO-1 response</span></span>
<span class="line"><span class="s_22m8k2">todos</span><span class="s_1jjt6x">.</span><span class="s_22m8k2">setValue</span><span class="s_1jjt6x">.</span><span class="s_11933w">error</span><span class="s_1th9sy"> // the failure</span></span></code></pre></div><p>Test <code>error</code>, not <code>data</code>, to tell a failed submit from a successful one. <code>if (!todos.setValue.data)</code> used to mean &quot;the last save failed&quot; and no longer does.</p></li><li><p><code>error</code> is no longer cleared when a submit starts. It used to be, which erased the error of a sibling submit still in flight. It now stands until the newest submit settles. To blank an error banner while a retry runs, hide it on <code>loading</code> yourself.</p></li><li><p><strong><code>submit()</code> rejects on any failure.</strong> It resolves with the response, or rejects with the error. A failed <code>validate</code> already rejected; a failed request used to resolve with <code>null</code>. Both reject now.</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">// Before</span></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> doc</span><span class="s_2ekfrt"> =</span><span class="s_29n2kq"> await</span><span class="s_22m8k2"> todos</span><span class="s_1jjt6x">.</span><span class="s_11933w">insert</span><span class="s_1jjt6x">.</span><span class="s_indoxt">submit</span><span class="s_13ahmt">({</span><span class="s_r4oegk"> title</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">Buy milk</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> })</span></span>
<span class="line"><span class="s_50ecpt">if</span><span class="s_13ahmt"> (</span><span class="s_50ecpt">!</span><span class="s_22m8k2">doc</span><span class="s_13ahmt">)</span><span class="s_29n2kq"> return</span><span class="s_indoxt"> showError</span><span class="s_13ahmt">(</span><span class="s_22m8k2">todos</span><span class="s_1jjt6x">.</span><span class="s_22m8k2">insert</span><span class="s_1jjt6x">.</span><span class="s_11933w">error</span><span class="s_13ahmt">)</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">// After</span></span>
<span class="line"><span class="s_50ecpt">try</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_252irl">  const</span><span class="s_295sjd"> doc</span><span class="s_2ekfrt"> =</span><span class="s_29n2kq"> await</span><span class="s_22m8k2"> todos</span><span class="s_1jjt6x">.</span><span class="s_11933w">insert</span><span class="s_1jjt6x">.</span><span class="s_indoxt">submit</span><span class="s_13ahmt">({ </span><span class="s_r4oegk">title</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">Buy milk</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> })</span></span>
<span class="line"><span class="s_13ahmt">}</span><span class="s_50ecpt"> catch</span><span class="s_13ahmt"> (</span><span class="s_22m8k2">e</span><span class="s_13ahmt">)</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_indoxt">  showError</span><span class="s_13ahmt">(</span><span class="s_22m8k2">e</span><span class="s_13ahmt">)</span></span>
<span class="line"><span class="s_13ahmt">}</span></span></code></pre></div><p><code>null</code> no longer means &quot;it failed&quot;. A server that answers with <code>null</code> resolves with <code>null</code>, like any other response. Every <code>if (!result)</code> check after a <code>submit()</code> has to become a <code>try</code> / <code>catch</code> or a <code>.catch()</code>, and an unawaited <code>submit()</code> now needs a <code>.catch()</code> or it becomes an unhandled rejection.</p></li><li><p><code>useList</code>&#39;s <code>insert</code> and <code>delete</code> now send to the <code>baseUrl</code> you passed to <code>useList</code>. They used to ignore it and hit the current origin. <code>setValue</code> already honoured it, so all three write methods now agree. <code>useDoctype</code> was never affected.</p></li><li><p>A stale <code>setValue</code> or <code>delete</code> on the same row no longer writes the shared document and list stores, and no longer triggers <code>useList</code>&#39;s auto-refetch. Every request carries a dispatch number, and a store rejects a write that a later-dispatched request already made. Submits with different keys, and keyless submits such as inserts, stay independent and all of their hooks still fire. Nothing to change — this is here so you can drop the workarounds.</p></li></ul><h3 id="usedoc-writes-and-usenewdoc" tabindex="-1"><code>useDoc</code> writes and <code>useNewDoc</code> <a class="header-anchor" href="#usedoc-writes-and-usenewdoc" aria-label="Permalink to “useDoc writes and useNewDoc”">​</a></h3><p><code>useDoc</code>&#39;s <code>setValue</code>, <code>delete</code> and every <code>methods:</code> entry, and all of <code>useNewDoc</code>, held one shared request too. Each submit now sends its own. They keep the full <code>useCall</code> surface — same members, same types — so there is nothing to rename.</p><p>One silent behavior change: <strong>a second submit no longer cancels the first.</strong> Both requests reach the server. If you relied on the abort to drop a superseded save, debounce or guard the call site yourself. <code>data</code> and <code>error</code> follow the same newest-wins rule as <code>useDoctype</code> above, and <code>loading</code> stays <code>true</code> until every submit settles.</p><h2 id="data-fetching-exports" tabindex="-1">Data fetching (exports) <a class="header-anchor" href="#data-fetching-exports" aria-label="Permalink to “Data fetching (exports)”">​</a></h2><p><code>useFrappeFetch</code> is no longer exported. It is the raw <code>createFetch</code> instance <code>useCall</code>, <code>useDoc</code> and <code>useList</code> are built on: it sets the Frappe headers and parses the response, and leaves the URL, the params and the caching to you. Pick the composable that matches what you are fetching.</p><table tabindex="0"><thead><tr><th>Before</th><th>After</th></tr></thead><tbody><tr><td><code>useFrappeFetch(&#39;/api/v2/method/…&#39;)</code></td><td><code>useCall({ url })</code></td></tr><tr><td><code>useFrappeFetch(&#39;/api/v2/document/…&#39;)</code></td><td><code>useDoc({ doctype, name })</code></td></tr><tr><td><code>useFrappeFetch(&#39;/api/v2/document/…?…&#39;)</code></td><td><code>useList({ doctype, … })</code></td></tr></tbody></table><p>This is a build failure at the import, so nothing changes silently.</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">// Before</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">useFrappeFetch</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"><span class="s_252irl">const</span><span class="s_1jjt6x"> {</span><span class="s_295sjd"> data</span><span class="s_1jjt6x"> }</span><span class="s_2ekfrt"> =</span><span class="s_indoxt"> useFrappeFetch</span><span class="s_13ahmt">(</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">/api/v2/method/ping</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt">)</span><span class="s_1jjt6x">.</span><span class="s_indoxt">get</span><span class="s_13ahmt">()</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">// After</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">useCall</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> ping</span><span class="s_2ekfrt"> =</span><span class="s_indoxt"> useCall</span><span class="s_13ahmt">({</span><span class="s_r4oegk"> url</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">/api/v2/method/ping</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> })</span></span></code></pre></div><p><code>FrappeResponseError</code> is exported now. A Frappe error response raises it — it lands on <code>.error</code>, and the write methods above reject with it. The class was never exported, so you could not tell it apart from a network or parse failure. Narrow it with <code>instanceof</code> and you get <code>title</code>, <code>type</code>, <code>indicator</code> and <code>exception</code>:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">FrappeResponseError</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_50ecpt">try</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_29n2kq">  await</span><span class="s_22m8k2"> todos</span><span class="s_1jjt6x">.</span><span class="s_11933w">insert</span><span class="s_1jjt6x">.</span><span class="s_indoxt">submit</span><span class="s_13ahmt">({ </span><span class="s_r4oegk">title</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">Buy milk</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> })</span></span>
<span class="line"><span class="s_13ahmt">}</span><span class="s_50ecpt"> catch</span><span class="s_13ahmt"> (</span><span class="s_22m8k2">e</span><span class="s_13ahmt">)</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_50ecpt">  if</span><span class="s_13ahmt"> (</span><span class="s_22m8k2">e</span><span class="s_2ekfrt"> instanceof</span><span class="s_euu481"> FrappeResponseError</span><span class="s_13ahmt">) {</span></span>
<span class="line"><span class="s_indoxt">    showError</span><span class="s_13ahmt">(</span><span class="s_22m8k2">e</span><span class="s_1jjt6x">.</span><span class="s_11933w">title</span><span class="s_1jjt6x">,</span><span class="s_22m8k2"> e</span><span class="s_1jjt6x">.</span><span class="s_11933w">type</span><span class="s_13ahmt">)</span></span>
<span class="line"><span class="s_13ahmt">  } </span><span class="s_50ecpt">else</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_50ecpt">    throw</span><span class="s_22m8k2"> e</span></span>
<span class="line"><span class="s_13ahmt">  }</span></span>
<span class="line"><span class="s_13ahmt">}</span></span></code></pre></div><h2 id="tree" tabindex="-1">Tree <a class="header-anchor" href="#tree" aria-label="Permalink to “Tree”">​</a></h2><p>The Tree was rebuilt from a single recursive <code>node</code> renderer into a stateful forest. It takes a <code>nodes</code> array and scopes its per-row slots as <code>#item-*</code>. Each node still owns its expansion via an <code>expanded</code> field, now defaulting to open — set <code>expanded: false</code> to collapse one (v0 used <code>defaultCollapsed</code>). The <code>options</code> blob is gone — sizing moves to CSS variables. Keyboard navigation, <code>role=&quot;tree&quot;</code> ARIA, and opt-in drag-and-drop are new.</p><table tabindex="0"><thead><tr><th>Before</th><th>After</th></tr></thead><tbody><tr><td><code>:node=&quot;root&quot;</code> (single root object)</td><td><code>:nodes=&quot;[root]&quot;</code> (array of roots)</td></tr><tr><td><code>node.collapsed</code> / internal collapse</td><td><code>node.expanded</code> (inverted, on each node)</td></tr><tr><td><code>:options=&quot;{ rowHeight, indentWidth }&quot;</code></td><td><code>--tree-row-height</code> / <code>--tree-indent</code> CSS vars</td></tr><tr><td><code>:options=&quot;{ showIndentationGuides }&quot;</code></td><td><code>guides=&quot;connectors&quot; | &quot;lines&quot; | &quot;none&quot;</code></td></tr><tr><td><code>:options=&quot;{ defaultCollapsed: true }&quot;</code></td><td><code>expanded: false</code> per node, or <code>v-model:expanded</code> to toggle all</td></tr><tr><td><code>#node=&quot;{ node, isCollapsed, toggleCollapsed }&quot;</code></td><td><code>#item=&quot;{ node, expanded, toggle, … }&quot;</code></td></tr><tr><td><code>#label</code></td><td><code>#item-label</code></td></tr><tr><td><code>#icon</code></td><td>built-in chevron; override via <code>#item</code></td></tr></tbody></table><p>Nothing here fails loudly. <code>:node</code> and <code>:options</code> become fall-through attributes, and content passed to the old <code>#node</code> / <code>#label</code> / <code>#icon</code> slots is discarded — the default row renders in its place. Only the now-required <code>nodes</code> prop warns, and only in dev; a production build renders an empty tree. Grep for <code>:node=</code>, <code>:options=</code>, <code>#node</code>, <code>#label</code> and <code>#icon</code> on <code>Tree</code> specifically.</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Tree</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">node</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">root</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> node-key</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">name</span><span class="s_w1p9wo">&quot;</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">options</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_13ahmt">{</span><span class="s_r4oegk"> defaultCollapsed</span><span class="s_1jjt6x">: </span><span class="s_40mev6">false</span><span class="s_13ahmt"> }</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;template #label=&quot;{ node }&quot;&gt;{{ node.title }}&lt;/template&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">Tree</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Tree</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">nodes</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_13ahmt">[</span><span class="s_11933w">root</span><span class="s_13ahmt">]</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> node-key</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">name</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;template #item-label=&quot;{ node }&quot;&gt;{{ node.title }}&lt;/template&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">Tree</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p><code>v-model:expanded</code> is a boolean expand/collapse-all switch (bind it to a button), not a per-node value.</p><p>Drag-and-drop is opt-in: set <code>draggable</code>, gate drops with <code>:move=&quot;({ node, target, position }) =&gt; …&quot;</code>, and persist from <code>@drag-end=&quot;(info) =&gt; …&quot;</code> — <code>info</code> is <code>{ node, from, to, position, oldIndex, newIndex }</code>, or <code>null</code> when the drag is cancelled.</p><h2 id="icons" tabindex="-1">Icons <a class="header-anchor" href="#icons" aria-label="Permalink to “Icons”">​</a></h2><p>The single recommended way to pass an icon anywhere in the library is a <code>lucide-*</code> string (rendered via the Tailwind mask plugin) or a <code>Component</code> escape hatch (P11). <code>FeatherIcon</code> is removed per ADR-0008 — it shipped <code>@deprecated</code> in code, so nothing marked deprecated ships in <code>1.0.0</code>.</p><p><strong>Breaking, loud:</strong> <code>import { FeatherIcon } from &#39;frappe-ui&#39;</code> and <code>&lt;FeatherIcon&gt;</code> fail at the import. Replace a direct usage with the <code>lucide-*</code> class form:</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">FeatherIcon</span><span class="s_1i4ay4"> name</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">plus</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> class</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">size-4</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">span</span><span class="s_1i4ay4"> class</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">lucide-plus size-4</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> aria-hidden</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">true</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span></code></pre></div><p>Feather and lucide share most icon names, so <code>&lt;FeatherIcon name=&quot;x&quot;&gt;</code> → <code>&lt;span class=&quot;lucide-x&quot;&gt;</code> is usually a direct rename — check each name individually against <a href="https://lucide.dev/icons" target="_blank" rel="noreferrer">lucide.dev</a> since a few differ or were renamed.</p><p><strong>Breaking, silent:</strong> every icon-name prop across the library (<code>Button.icon</code> / <code>iconLeft</code> / <code>iconRight</code>, <code>Dialog.icon</code>, <code>Alert.icon</code>, <code>SidebarCard.icon</code>, <code>Dropdown</code>/<code>ContextMenu</code> item <code>icon</code>, <code>TabButtons</code> options <code>icon</code> / <code>iconLeft</code>, <code>TabTrigger.icon</code> / <code>iconLeft</code>, the <code>Icon</code> component&#39;s <code>name</code> prop) used to render a bare feather-style name (e.g. <code>&quot;edit&quot;</code>, <code>&quot;chevron-down&quot;</code>) via <code>FeatherIcon</code>. That fallback is gone: only a <code>lucide-*</code> string, an emoji or symbol glyph, or a <code>Component</code> renders. Any other string renders nothing. No build or type error — the icon silently disappears. A dev-mode console warning names the component, the prop, and the offending value once per (component, prop). Prefix the name with <code>lucide-</code>:</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Button</span><span class="s_1i4ay4"> icon</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">plus</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Button</span><span class="s_1i4ay4"> icon</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">lucide-plus</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span></code></pre></div><p>Same for icon-name strings in <code>Dropdown</code> options:</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">// Before</span></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> options</span><span class="s_2ekfrt"> =</span><span class="s_13ahmt"> [{</span><span class="s_r4oegk"> label</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">Edit</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_r4oegk"> icon</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">edit</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> }]</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">// After</span></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> options</span><span class="s_2ekfrt"> =</span><span class="s_13ahmt"> [{</span><span class="s_r4oegk"> label</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">Edit</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_r4oegk"> icon</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">lucide-pen</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> }]</span></span></code></pre></div><h2 id="card-listitem-standalone-toast-removed" tabindex="-1">Card, ListItem, standalone <code>&lt;Toast&gt;</code> (removed) <a class="header-anchor" href="#card-listitem-standalone-toast-removed" aria-label="Permalink to “Card, ListItem, standalone &lt;Toast&gt; (removed)”">​</a></h2><p>Three unmaintained wrappers are gone in v1, per ADR-0008 — each shipped <code>@deprecated</code> in code and had zero call sites left across our census of downstream apps.</p><p><strong><code>Card</code></strong> wrapped a title/subtitle/actions layout with a manual loading state. There&#39;s no drop-in replacement; rebuild the layout with plain markup, using <a href="./components/loadingtext"><code>LoadingText</code></a> or <a href="./components/skeleton"><code>Skeleton</code></a> for the loading state:</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Card</span><span class="s_1i4ay4"> title</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">Title</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> subtitle</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">Subtitle</span><span class="s_w1p9wo">&quot;</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">loading</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">loading</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;template #actions&gt;&lt;Button label=&quot;Edit&quot; /&gt;&lt;/template&gt;</span></span>
<span class="line"><span class="s_6am9cx">  Content</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">Card</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">div</span><span class="s_1i4ay4"> class</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">flex flex-col rounded-6 border px-6 py-5</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;div class=&quot;flex items-baseline justify-between&quot;&gt;</span></span>
<span class="line"><span class="s_6am9cx">    &lt;h2 class=&quot;text-lg font-semibold&quot;&gt;Title&lt;/h2&gt;</span></span>
<span class="line"><span class="s_6am9cx">    &lt;Button label=&quot;Edit&quot; /&gt;</span></span>
<span class="line"><span class="s_1zd9e2">  &lt;/</span><span class="s_1uuh8p">div</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">  &lt;</span><span class="s_1uuh8p">p</span><span class="s_1i4ay4"> class</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">mt-1.5 text-ink-gray-6</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span><span class="s_6am9cx">Subtitle</span><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">p</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">  &lt;</span><span class="s_1uuh8p">LoadingText</span><span class="s_50ecpt"> v-if</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">loading</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> class</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">mt-4</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"><span class="s_1zd9e2">  &lt;</span><span class="s_1uuh8p">div</span><span class="s_50ecpt"> v-else</span><span class="s_1i4ay4"> class</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">mt-4</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span><span class="s_6am9cx">Content</span><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">div</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_6am9cx">/</span><span class="s_1uuh8p">div</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p><strong><code>ListItem</code></strong> rendered a title/subtitle/actions row. Same story — no drop-in replacement, rebuild with plain markup:</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">ListItem</span><span class="s_1i4ay4"> title</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">Title</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> subtitle</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">Subtitle</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;template #actions&gt;&lt;Button label=&quot;Edit&quot; /&gt;&lt;/template&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">ListItem</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">div</span><span class="s_1i4ay4"> class</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">flex items-center justify-between py-3</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;div&gt;</span></span>
<span class="line"><span class="s_6am9cx">    &lt;h3 class=&quot;font-medium&quot;&gt;Title&lt;/h3&gt;</span></span>
<span class="line"><span class="s_6am9cx">    &lt;p class=&quot;text-ink-gray-6&quot;&gt;Subtitle&lt;/p&gt;</span></span>
<span class="line"><span class="s_1zd9e2">  &lt;/</span><span class="s_1uuh8p">div</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">  &lt;</span><span class="s_1uuh8p">Button</span><span class="s_1i4ay4"> label</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">Edit</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_6am9cx">/</span><span class="s_1uuh8p">div</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p><strong>Standalone <code>&lt;Toast&gt;</code></strong> — <code>import { Toast } from &#39;frappe-ui&#39;</code> and <code>&lt;Toast&gt;</code> fail at the import. This only removes the raw <code>ToastRoot</code>-based component; the imperative API is unaffected and is what you almost certainly want:</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Toast</span><span class="s_1i4ay4"> v-model</span><span class="s_1jjt6x">:</span><span class="s_1i4ay4">open</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">open</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> message</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">Saved</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> type</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">success</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1i4ay4"> setup</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">toast</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"><span class="s_22m8k2">toast</span><span class="s_1jjt6x">.</span><span class="s_indoxt">success</span><span class="s_13ahmt">(</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">Saved</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt">)</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p><code>&lt;ToastProvider&gt;</code> (mount once near your app root) is unchanged. The current API is plain <code>toast()</code> plus <code>toast.success()</code> / <code>toast.error()</code> / <code>toast.warning()</code> / <code>toast.info()</code>. v0&#39;s <code>toast.create()</code>, <code>toast.remove()</code> and <code>toast.removeAll()</code> still work, but warn once in dev — move them to <code>toast(...)</code> and <code>toast.dismiss(...)</code>.</p><h2 id="tokens" tabindex="-1">Tokens <a class="header-anchor" href="#tokens" aria-label="Permalink to “Tokens”">​</a></h2><p>Run the v2 token codemod from the app you are migrating:</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_euu481">npx</span><span class="s_2d41qv"> --package</span><span class="s_2575z4"> frappe-ui@beta</span><span class="s_2575z4"> tokens-v2</span><span class="s_2d41qv"> --dry-run</span><span class="s_2575z4"> .</span></span></code></pre></div><p>Review the output, then run it without <code>--dry-run</code>:</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_euu481">npx</span><span class="s_2d41qv"> --package</span><span class="s_2575z4"> frappe-ui@beta</span><span class="s_2575z4"> tokens-v2</span><span class="s_2575z4"> .</span></span></code></pre></div><p>The codemod renames espresso color tokens like <code>bg-surface-white</code> to <code>bg-surface-base</code>, merges static text size + weight class pairs (for example <code>text-base font-medium</code> to <code>text-base-medium</code>), and renames the removed radius aliases (<code>rounded-md</code> → <code>rounded-5</code>, see below). Run it once per codebase; the token migration is not idempotent because some v2 names overlap with v0 names. The radius renames are idempotent and also run on already-migrated codebases.</p><p>In every mode, the codemod stays inside the directories you give it. A symlink whose real path leaves the target — a file or a directory — is skipped and listed at the end of the run. Run the codemod on each real package root, so a shared package linked into several apps is migrated once.</p><p>After upgrading to <code>frappe-ui@1.0.0-beta.11</code>, run the codemod again. Apps that already ran it will only get the typography correction (<code>text-lg</code> → <code>text-md</code>, <code>text-xl</code> → <code>text-lg</code>, ...) and the radius renames. Apps that still have pre-v2 color tokens can pass <code>--force</code>, but review the output carefully because color tokens may double-shift.</p><p>Already ran the typography correction too? Pass <code>--radius-only</code>. It performs only the radius renames (safe to repeat) and reports removed tokens — it never touches color or text-size names, so nothing can double-shift.</p><h3 id="unused-tokens-and-utilities-removed" tabindex="-1">Unused tokens and utilities removed <a class="header-anchor" href="#unused-tokens-and-utilities-removed" aria-label="Permalink to “Unused tokens and utilities removed”">​</a></h3><p>A pre-<code>1.0.0</code> audit (#940) removed the token names below — all had zero call sites across frappe-ui and every consumer app. Each is a <strong>silent</strong> break: the class or <code>--*</code> variable just stops applying, with no build or type error.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_wvjl67">text-tiny</span></span>
<span class="line"><span class="s_wvjl67">text-13xl / text-14xl / text-15xl / text-16xl (and their -medium/-semibold/-bold/-black variants)</span></span>
<span class="line"><span class="s_wvjl67">shadow-status</span></span>
<span class="line"><span class="s_wvjl67">--elevation-status</span></span>
<span class="line"><span class="s_wvjl67">surface-alert-button-default / -info / -success / -warning / -error</span></span>
<span class="line"><span class="s_wvjl67">ink-alert-button-default / -info / -success / -warning / -error</span></span>
<span class="line"><span class="s_wvjl67">surface-alpha-gray-2-overlay</span></span>
<span class="line"><span class="s_wvjl67">surface-alpha-red-1 … surface-alpha-red-7</span></span>
<span class="line"><span class="s_wvjl67">outline-alpha-red-2 / -3 / -4</span></span></code></pre></div><p>The codemod reports only some of these: the dead text sizes, the <code>text-*-black</code> styles, and the two alpha-red families. It has no rule for <code>shadow-status</code>, <code>--elevation-status</code>, the <code>alert-button</code> tokens, or <code>surface-alpha-gray-2-overlay</code> — grep for those five by hand.</p><p>If your build used any of these, replace them with the nearest step on the regular scale — e.g. <code>text-16xl</code> → <code>text-12xl</code>, <code>shadow-status</code> → <code>shadow-sm</code>, <code>surface-alert-button-error</code> → <code>surface-red-2</code> (or whichever <code>variant</code>+<code>theme</code> pairing the design calls for).</p><h3 id="radius-aliases-removed" tabindex="-1">Radius aliases removed <a class="header-anchor" href="#radius-aliases-removed" aria-label="Permalink to “Radius aliases removed”">​</a></h3><p>The named radius aliases are removed in <code>1.0.0</code>. Numbered tokens are the only radius vocabulary now (<a href="https://github.com/frappe/frappe-ui/blob/main/spec/adr/0006-numbered-radius-tokens.md" target="_blank" rel="noreferrer">ADR-0006</a>). <code>rounded-none</code> and <code>rounded-full</code> are kept.</p><p>This is a <strong>silent</strong> break. The preset replaces Tailwind&#39;s <code>borderRadius</code> scale, so an unmigrated <code>rounded-md</code> emits no CSS at all — no build error, no type error, just square corners. Run the codemod, then grep for leftover aliases.</p><table tabindex="0"><thead><tr><th>Before</th><th>After</th><th>px</th></tr></thead><tbody><tr><td><code>rounded</code></td><td><code>rounded-4</code></td><td>8</td></tr><tr><td><code>rounded-sm</code></td><td><code>rounded-1</code></td><td>4</td></tr><tr><td><code>rounded-md</code></td><td><code>rounded-5</code></td><td>10</td></tr><tr><td><code>rounded-lg</code></td><td><code>rounded-6</code></td><td>12</td></tr><tr><td><code>rounded-xl</code></td><td><code>rounded-7</code></td><td>16</td></tr><tr><td><code>rounded-2xl</code></td><td><code>rounded-8</code></td><td>20</td></tr></tbody></table><p>The same map applies to every directional and corner form (<code>rounded-t-lg</code> → <code>rounded-t-6</code>, <code>rounded-tl-sm</code> → <code>rounded-tl-1</code>), to the logical sides (<code>rounded-ss-md</code> → <code>rounded-ss-5</code>, and the same for <code>s</code>, <code>e</code>, <code>se</code>, <code>es</code>, <code>ee</code>), to the bare directional aliases (<code>rounded-t</code> → <code>rounded-t-4</code>), and to variant prefixes (<code>hover:rounded-2xl</code> → <code>hover:rounded-8</code>). Pixel values are identical — the migration changes vocabulary, not rendering.</p><p>The codemod handles all of these. One caveat: the bare word <code>rounded</code> is plain English, so the codemod only rewrites it inside quoted strings and <code>@apply</code> rules. A class list inside a multi-line template literal can be missed — grep for bare <code>rounded</code> after running it.</p><p>The alias CSS variables go away with the aliases. Hand-written CSS that reads <code>var(--radius-sm)</code> / <code>var(--radius-md)</code> / <code>var(--radius-lg)</code> / <code>var(--radius-xl)</code> / <code>var(--radius-2xl)</code> resolves to nothing — the same silent break. The codemod only rewrites <code>rounded-*</code> classes, so grep for <code>--radius-(sm|md|lg|xl|2xl)</code> and switch to the numbered variables (<code>var(--radius-5)</code> for the old <code>--radius-md</code>, same map as above).</p><h3 id="text-black-styles-removed" tabindex="-1"><code>text-*-black</code> styles removed <a class="header-anchor" href="#text-black-styles-removed" aria-label="Permalink to “text-*-black styles removed”">​</a></h3><p>The <code>text-&lt;size&gt;-black</code> / <code>text-p-&lt;size&gt;-black</code> style classes are removed — zero usage anywhere, and the Figma weights behind them were corrupt export data. This is also a <strong>silent</strong> break: the class stops emitting CSS.</p><p>The codemod no longer merges <code>font-extrabold</code> (or <code>font-black</code>) onto a <code>text-*-black</code> class. It flags the pair under &quot;needs manual attention&quot; instead. If you need weight 800, keep <code>font-extrabold</code>; there is no letter-spacing-corrected style class for it.</p><h3 id="ink-chromatic-scales-shift-one-level" tabindex="-1">Ink chromatic scales shift one level <a class="header-anchor" href="#ink-chromatic-scales-shift-one-level" aria-label="Permalink to “Ink chromatic scales shift one level”">​</a></h3><p>The updated espresso v2 tokens shift every chromatic ink scale down one level: the new <code>ink-red-1</code> is the old <code>ink-red-2</code>, and so on for all 11 chromatic families. The scales now end at <code>-9</code>. <code>ink-gray</code> keeps its own 9-step scale and does not shift. This is a <strong>silent</strong> break: every <code>ink-&lt;family&gt;-N</code> site renders one shade off after the token update.</p><p>Run the codemod once with <code>--ink-shift</code>:</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_euu481">npx</span><span class="s_2d41qv"> --package</span><span class="s_2575z4"> frappe-ui@beta</span><span class="s_2575z4"> tokens-v2</span><span class="s_2d41qv"> --ink-shift</span><span class="s_2575z4"> .</span></span></code></pre></div><p>Run the codemod in the same change as the frappe-ui upgrade that ships the shifted tokens. The upgrade without the codemod renders one shade off. The codemod without the upgrade also renders one shade off. Land both together.</p><p>Add <code>--dry-run</code> first to review the renames before they apply:</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_euu481">npx</span><span class="s_2d41qv"> --package</span><span class="s_2575z4"> frappe-ui@beta</span><span class="s_2575z4"> tokens-v2</span><span class="s_2d41qv"> --ink-shift</span><span class="s_2d41qv"> --dry-run</span><span class="s_2575z4"> .</span></span></code></pre></div><p><code>--ink-shift</code> cannot be combined with <code>--force</code> or <code>--radius-only</code>; the run exits with an error rather than hiding which renames applied. A dry run is not a safety probe either: it only warns when it finds a run-once marker, while a real run refuses outright.</p><p>This mode runs only the ink shift — no color renames, no typography, no radius renames. Run it exactly once per codebase. There is no way to detect a prior run from file content (<code>ink-red-5</code> is a valid name before and after), so a second run double-shifts. To guard against that, <code>--ink-shift</code> takes directory targets only, and a real run writes a <code>.tokens-v2-ink-shift</code> marker file in each target directory. It refuses to run again while a marker exists in the target, an ancestor, or anywhere in the target subtree. The marker is written before the first file rewrite, so an interrupted run refuses to retry instead of double-shifting; restore the tree with git, delete the marker, and re-run. Commit the marker with the migration — on a fresh clone without it the guard is gone, and a teammate&#39;s re-run double-shifts. Delete it only to re-run the shift on purpose.</p><p>Each marker is created exclusively, so two runs on the same directory cannot both start: the second stops before it rewrites anything. For nested targets (a repo root and one of its subdirectories) the run searches again after it claims its markers, and stops if another run claimed an overlapping tree. Both runs can stop this way. Neither has rewritten a file at that point, so re-run whichever tree is still unshifted.</p><p>The marker search follows the same symlink rule as the run: a marker in a linked external package never blocks a target the run would not rewrite. Run the codemod on each real package root directly, so every migrated tree gets its own marker. If the refusal names a marker inside a vendored dependency (for example <code>vendor/frappe-ui/.tokens-v2-ink-shift</code>), that dependency is already shifted — leave its marker alone and target the directories that do not contain it. Pointing at the app root will not help: the search walks the whole subtree, so any ancestor of the vendored copy finds the same marker and refuses again. Target <code>src/</code> and your other own trees instead.</p><p>The old <code>ink-&lt;family&gt;-1</code> step was white. The new <code>-1</code> is a light tint, so these sites have no automatic destination. The codemod flags them under &quot;needs manual attention&quot;. The usual fix is <code>text-white</code> (or the literal CSS color <code>white</code> in hand-written CSS).</p><h2 id="editor" tabindex="-1">Editor <a class="header-anchor" href="#editor" aria-label="Permalink to “Editor”">​</a></h2><p>The v0 monolith <code>&lt;TextEditor&gt;</code> (imported from <code>frappe-ui</code>) is replaced by the <code>frappe-ui/editor</code> family: a headless <code>&lt;Editor&gt;</code> you compose with <strong>kits</strong> (bundled, configurable extension sets) and <strong>building-block</strong> menus. Everything moves to the <code>frappe-ui/editor</code> subpath; <code>TextEditor</code> and its siblings (<code>TextEditorBubbleMenu</code>, <code>TextEditorFixedMenu</code>, <code>TextEditorFloatingMenu</code>, <code>TextEditorContent</code>, <code>createEditorButton</code>) are removed from top-level <code>frappe-ui</code> in <code>1.0.0</code>, and so are the v0 extension helpers <code>ImageExtension</code> and <code>createSuggestionExtension</code> with their types <code>SetImageOptions</code>, <code>BaseSuggestionItem</code> and <code>CreateSuggestionExtensionOptions</code> — nothing editor-related is exported from root. See the <a href="./molecules/editor">Editor</a> page for the full API and recipes.</p><p>Not migrated yet? All eleven v0 names are parked, unchanged, in <code>frappe-ui/experimental</code> as an interim import path. It is unstable — no deprecation window — and will be removed once consumers migrate:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_4q1z3w">  TextEditor</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_4q1z3w">  TextEditorBubbleMenu</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_4q1z3w">  TextEditorFixedMenu</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_4q1z3w">  TextEditorFloatingMenu</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_4q1z3w">  TextEditorContent</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_4q1z3w">  createEditorButton</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_4q1z3w">  ImageExtension</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_4q1z3w">  createSuggestionExtension</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">}</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui/experimental</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_50ecpt"> type</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_4q1z3w">  SetImageOptions</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_4q1z3w">  BaseSuggestionItem</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_4q1z3w">  CreateSuggestionExtensionOptions</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">}</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui/experimental</span><span class="s_w1p9wo">&#39;</span></span></code></pre></div><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">// Before</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">TextEditor</span><span class="s_1jjt6x">,</span><span class="s_4q1z3w"> TextEditorFixedMenu</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"><span class="s_1th9sy">// After</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_4q1z3w">  Editor</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_4q1z3w">  EditorFixedMenu</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_4q1z3w">  RichTextKit</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_4q1z3w">  articleToolbar</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">}</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui/editor</span><span class="s_w1p9wo">&#39;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Before</th><th>After</th></tr></thead><tbody><tr><td><code>import … from &#39;frappe-ui&#39;</code></td><td><code>import … from &#39;frappe-ui/editor&#39;</code></td></tr><tr><td><code>&lt;TextEditor&gt;</code></td><td><code>&lt;Editor&gt;</code></td></tr><tr><td><code>:content=&quot;x&quot; @change=&quot;x = $event&quot;</code></td><td><code>v-model=&quot;x&quot;</code> (<code>@change</code> still emitted)</td></tr><tr><td>HTML string only</td><td><code>v-model</code> + <code>format=&quot;json&quot;</code> for a JSON value</td></tr><tr><td><code>:starterkit-options=&quot;{ heading: { levels } }&quot;</code></td><td><code>RichTextKit.configure({ heading: { levels } })</code> in <code>:extensions</code></td></tr><tr><td>auto-loaded extension set (no opt-out)</td><td>explicit <code>:extensions</code> — pick <code>CommentKit</code> / <code>RichTextKit</code> / <code>InlineKit</code></td></tr><tr><td><code>:mentions</code> / <code>:tags</code> props</td><td><code>kit.configure({ mention: { items, component }, tag: { items } })</code></td></tr><tr><td><code>:bubble-menu=&quot;true&quot;</code></td><td><code>&lt;EditorBubbleMenu :items=&quot;articleToolbar&quot;&gt;</code> in the default slot</td></tr><tr><td><code>:floating-menu=&quot;true&quot;</code></td><td><code>&lt;EditorFloatingMenu :items&gt;</code></td></tr><tr><td><code>&lt;TextEditorFixedMenu :buttons&gt;</code></td><td><code>&lt;EditorFixedMenu :items&gt;</code></td></tr><tr><td><code>&lt;TextEditorContent&gt;</code></td><td><code>&lt;EditorContent&gt;</code></td></tr><tr><td>menu <code>:buttons</code></td><td>menu <code>:items</code></td></tr><tr><td>hand-rolled <code>textEditorMenuButtons</code> array</td><td><code>commentToolbar</code> / <code>articleToolbar</code> / <code>minimalToolbar</code> presets</td></tr><tr><td><code>#top</code> / <code>#bottom</code> / <code>#editor</code> slots</td><td>one default slot — you render <code>EditorContent</code> + menus yourself</td></tr><tr><td><code>:uploadFunction</code> (optional, frappe default)</td><td><code>:upload-function</code> (required to enable uploads)</td></tr></tbody></table><h3 id="compose-don-t-configure" tabindex="-1">Compose, don&#39;t configure <a class="header-anchor" href="#compose-don-t-configure" aria-label="Permalink to “Compose, don&#39;t configure”">​</a></h3><p>v0 took every option as a prop on <code>&lt;TextEditor&gt;</code> and auto-loaded every extension. v1 renders no chrome of its own — you place the building blocks inside its default slot and they pick up the editor from context (the <code>:editor</code> prop is only needed when composing primitives without <code>&lt;Editor&gt;</code>):</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1i4ay4"> setup</span><span class="s_1i4ay4"> lang</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">ts</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">ref</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">vue</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_4q1z3w">  Editor</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_4q1z3w">  EditorContent</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_4q1z3w">  EditorBubbleMenu</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_4q1z3w">  RichTextKit</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_4q1z3w">  articleToolbar</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">}</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui/editor</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> content</span><span class="s_2ekfrt"> =</span><span class="s_indoxt"> ref</span><span class="s_13ahmt">(</span><span class="s_w1p9wo">&#39;&#39;</span><span class="s_13ahmt">)</span></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> extensions</span><span class="s_2ekfrt"> =</span><span class="s_13ahmt"> [</span></span>
<span class="line"><span class="s_22m8k2">  RichTextKit</span><span class="s_1jjt6x">.</span><span class="s_indoxt">configure</span><span class="s_13ahmt">({</span><span class="s_r4oegk"> heading</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> {</span><span class="s_r4oegk"> levels</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> [</span><span class="s_40mev6">2</span><span class="s_1jjt6x">,</span><span class="s_40mev6"> 3</span><span class="s_1jjt6x">,</span><span class="s_40mev6"> 4</span><span class="s_1jjt6x">,</span><span class="s_40mev6"> 5</span><span class="s_1jjt6x">,</span><span class="s_40mev6"> 6</span><span class="s_13ahmt">]</span><span class="s_13ahmt"> }</span><span class="s_13ahmt"> })</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">]</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">template</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">  &lt;</span><span class="s_wac0bt">Editor</span><span class="s_1i4ay4"> v-model</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">content</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> :extensions</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">extensions</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> placeholder</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">Write…</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">    &lt;</span><span class="s_wac0bt">EditorBubbleMenu</span><span class="s_1i4ay4"> :items</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">articleToolbar</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"><span class="s_1zd9e2">    &lt;</span><span class="s_wac0bt">EditorContent</span><span class="s_1i4ay4"> class</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">prose max-w-none</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"><span class="s_1zd9e2">  &lt;/</span><span class="s_wac0bt">Editor</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">template</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p>Pick the kit per surface: <code>CommentKit</code> (light — no table/toc/slash), <code>RichTextKit</code> (full document), <code>InlineKit</code> (single-line). Configure kit members in place rather than via props — e.g. mentions/tags through <code>kit.configure({ mention: {...}, tag: {...} })</code>. To keep the mention/tag nodes rendering but disable the live popups, pass <code>mention: { items: null }</code>.</p><p>For a fully custom layout (e.g. a title <code>&lt;textarea&gt;</code> as a sibling of the body), skip <code>&lt;Editor&gt;</code> and drive <code>useEditor</code> yourself — see <a href="./molecules/editor#composing-primitives">Composing primitives</a> — rendering <code>&lt;EditorContent&gt;</code> and the menus as siblings of your own markup.</p><h3 id="gotchas" tabindex="-1">Gotchas <a class="header-anchor" href="#gotchas" aria-label="Permalink to “Gotchas”">​</a></h3><ul><li><strong>Tailwind must scan frappe-ui&#39;s editor source.</strong> Menu icons are literal <code>lucide-*</code> class strings living in <code>frappe-ui/src/molecules/**</code>. Add that glob to your <code>tailwind.config.js</code> <code>content</code>, or the toolbar / bubble / floating icons silently won&#39;t be generated.</li><li><strong>Uploads need an explicit handler.</strong> v0 silently invoked the Frappe upload; v1 requires <code>:upload-function</code>. In a Frappe app: <code>(file) =&gt; useFileUpload().upload(file, {})</code>.</li><li><strong>TipTap must be v3.</strong> The v1 editor is built on TipTap 3 — pin <code>@tiptap/core</code>, <code>@tiptap/pm</code>, and <code>@tiptap/vue-3</code> to <code>^3</code>.</li></ul><h2 id="family-stylesheets-list-style-css-editor-style-css" tabindex="-1">Family stylesheets (list-style.css / editor-style.css) <a class="header-anchor" href="#family-stylesheets-list-style-css-editor-style-css" aria-label="Permalink to “Family stylesheets (list-style.css / editor-style.css)”">​</a></h2><p>The manual <code>frappe-ui/list-style.css</code> and <code>frappe-ui/editor-style.css</code> exports are removed. The <code>frappe-ui/list</code> and <code>frappe-ui/editor</code> barrels are now marked as side-effectful, so each family&#39;s CSS lands in your production build automatically when you import anything from its subpath.</p><p>Delete the manual imports; there is nothing to add back:</p><div class="language-css"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">/* Before */</span></span>
<span class="line"><span class="s_19y4hp">@</span><span class="s_50ecpt">import</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui/list-style.css</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">;</span></span>
<span class="line"><span class="s_19y4hp">@</span><span class="s_50ecpt">import</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui/editor-style.css</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">;</span></span>
<span class="line"><span class="s_1th9sy">/* After: nothing — the CSS ships with the subpath import */</span></span></code></pre></div><p>The build fails loudly (<code>Missing &quot;./list-style.css&quot; specifier in &quot;frappe-ui&quot; package</code>) until the lines are gone.</p><h2 id="frappe-ui-code-editor-removed" tabindex="-1"><code>frappe-ui/code-editor</code> (removed) <a class="header-anchor" href="#frappe-ui-code-editor-removed" aria-label="Permalink to “frappe-ui/code-editor (removed)”">​</a></h2><p>The subpath is gone. <code>CodeEditor</code>, <code>CodePreview</code> and <code>loadLanguage</code> move to <code>frappe-ui/experimental</code> (P14 — no stability promise). The components are unchanged; one import line changes per file. The build fails loudly until it does:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">// Before</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">CodeEditor</span><span class="s_1jjt6x">,</span><span class="s_4q1z3w"> CodePreview</span><span class="s_1jjt6x">,</span><span class="s_4q1z3w"> loadLanguage</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui/code-editor</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">// After</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">CodeEditor</span><span class="s_1jjt6x">,</span><span class="s_4q1z3w"> CodePreview</span><span class="s_1jjt6x">,</span><span class="s_4q1z3w"> loadLanguage</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui/experimental</span><span class="s_w1p9wo">&#39;</span></span></code></pre></div><p>The types move with them: <code>CodeLanguage</code>, <code>CodeEditorProps</code>, <code>CodeEditorEmits</code> and <code>CodePreviewProps</code>.</p><h2 id="hljs-theme-css-and-tailwind-tokens-js-removed" tabindex="-1"><code>hljs-theme.css</code> and <code>tailwind/tokens.js</code> (removed) <a class="header-anchor" href="#hljs-theme-css-and-tailwind-tokens-js-removed" aria-label="Permalink to “hljs-theme.css and tailwind/tokens.js (removed)”">​</a></h2><p>Two exports with no importers left are gone. Both breaks are loud — the specifier stops resolving.</p><table tabindex="0"><thead><tr><th>Removed</th><th>Replacement</th></tr></thead><tbody><tr><td><code>frappe-ui/hljs-theme.css</code></td><td>none — <code>frappe-ui/editor</code> ships its own code-block highlighting</td></tr><tr><td><code>frappe-ui/tailwind/tokens.js</code></td><td><code>frappe-ui/tailwind</code>, the preset, imported directly</td></tr></tbody></table><h2 id="frappe-ui-frappe-and-frappe-ui-drive-removed" tabindex="-1"><code>frappe-ui/frappe</code> and <code>frappe-ui/drive</code> (removed) <a class="header-anchor" href="#frappe-ui-frappe-and-frappe-ui-drive-removed" aria-label="Permalink to “frappe-ui/frappe and frappe-ui/drive (removed)”">​</a></h2><p>Both subpaths are gone in v1. frappe-ui is a UI library; the members that know about doctypes, onboarding flows, or billing moved to <code>@framework/ui</code> (the <code>ui/</code> package in the <a href="https://github.com/frappe/frappe" target="_blank" rel="noreferrer">frappe repo</a>). Every break here is loud — the import path stops resolving.</p><table tabindex="0"><thead><tr><th>Before (<code>frappe-ui/frappe</code>)</th><th>After</th></tr></thead><tbody><tr><td><code>useTelemetry</code>, <code>telemetryPlugin</code></td><td><code>@framework/ui</code></td></tr><tr><td><code>useOnboarding</code>, <code>GettingStartedBanner</code>, <code>IntermediateStepModal</code>, <code>HelpModal</code>, <code>showHelpModal</code>, <code>minimize</code></td><td><code>@framework/ui</code></td></tr><tr><td><code>TrialBanner</code>, <code>SignupBanner</code></td><td><code>@framework/ui</code></td></tr><tr><td><code>DataImport</code></td><td><code>@framework/ui</code></td></tr><tr><td><code>Link</code>, <code>LinkProps</code>, <code>LinkEmits</code>, <code>LinkExposed</code>, <code>LinkOption</code></td><td><code>@framework/ui</code> (superset, see below)</td></tr><tr><td><code>Filter</code></td><td><code>@framework/ui</code> (superset, see below)</td></tr><tr><td><code>OnboardingSteps</code>, <code>HelpCenter</code>, <code>showHelpCenter</code></td><td>removed — they live on inside <code>@framework/ui</code>&#39;s <code>HelpModal</code></td></tr><tr><td><code>frappe-ui/drive</code>, <code>frappe-ui/drive/*</code></td><td>removed, no replacement</td></tr></tbody></table><p><code>@framework/ui</code> peer-depends on <code>frappe-ui</code>, so add it as a dependency if your app does not carry it yet, then change the import path:</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">// Before</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">useTelemetry</span><span class="s_1jjt6x">,</span><span class="s_4q1z3w"> TrialBanner</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui/frappe</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">// After</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">useTelemetry</span><span class="s_1jjt6x">,</span><span class="s_4q1z3w"> TrialBanner</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">@framework/ui</span><span class="s_w1p9wo">&#39;</span></span></code></pre></div><p>Two replacements are supersets of what they replace — existing call sites work unchanged:</p><ul><li><code>Link</code> adds <code>redirectable</code> / <code>editable</code> props and <code>redirect</code> / <code>edit</code> emits.</li><li><code>Filter</code> adds a <code>useFilters</code> composable, <code>parseFilters</code> / <code>serializeFilters</code>, and an operator registry.</li></ul><p>The drive components were removed because the drive app already owns the live copy of all six; nothing imported the subpath.</p><p>Finally, drop the stale Tailwind glob. The <code>frappe/</code> directory no longer ships, so this line in <code>tailwind.config.js</code> scans nothing:</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">// Delete this line</span></span>
<span class="line"><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">./node_modules/frappe-ui/frappe/**/*.{vue,js,ts,jsx,tsx}</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span></code></pre></div><p>Better: replace the hand-copied list with the <a href="/docs/foundations/tailwind#the-content-export"><code>content</code> export</a>, which tracks the library&#39;s source directories for you.</p><h2 id="autocomplete-removed" tabindex="-1">Autocomplete (removed) <a class="header-anchor" href="#autocomplete-removed" aria-label="Permalink to “Autocomplete (removed)”">​</a></h2><p><code>Autocomplete</code> is gone in v1. It merged single- and multi-select via the <code>multiple</code> boolean; v1 splits them: <a href="./components/combobox"><code>Combobox</code></a> for single, <a href="./components/multiselect"><code>MultiSelect</code></a> for multiple.</p><p>The import fails, so your build tells you where every call site is. Three things inside those call sites change quietly instead, and each has a before/after below: the <strong>v-model payload</strong>, the <strong>group key</strong>, and the <strong><code>open</code> slot prop</strong>, which was a function and is now a boolean.</p><p>Sweep your codebase:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_euu481">grep</span><span class="s_2d41qv"> -rln</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">&lt;Autocomplete\\b</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4"> src</span><span class="s_2d41qv"> --include=</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">*.vue</span><span class="s_w1p9wo">&#39;</span><span class="s_1th9sy">   # find usages</span></span>
<span class="line"><span class="s_euu481">grep</span><span class="s_2d41qv"> -rln</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">:multiple</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4"> src</span><span class="s_2d41qv"> --include=</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">*.vue</span><span class="s_w1p9wo">&#39;</span><span class="s_1th9sy">         # these become MultiSelect</span></span>
<span class="line"><span class="s_euu481">grep</span><span class="s_2d41qv"> -rn</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">items:</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4"> src</span><span class="s_2d41qv"> --include=</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">*.vue</span><span class="s_w1p9wo">&#39;</span><span class="s_1th9sy">             # grouped options — see below</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Before (<code>Autocomplete</code>)</th><th>After</th></tr></thead><tbody><tr><td><code>:multiple=&quot;false&quot;</code> (default)</td><td>use <code>Combobox</code></td></tr><tr><td><code>:multiple=&quot;true&quot;</code></td><td>use <code>MultiSelect</code></td></tr><tr><td><code>v-model</code> (option or value)</td><td><code>v-model</code> (value / value array)</td></tr><tr><td><code>@change</code></td><td><code>@update:modelValue</code> (<code>@update:selectedOption</code> for the option)</td></tr><tr><td>grouped <code>{ group, items }</code></td><td>grouped <code>{ group, options }</code></td></tr><tr><td><code>placement</code> (string)</td><td><code>side</code> + <code>align</code></td></tr><tr><td><code>:showFooter</code></td><td><code>#footer</code> slot (MultiSelect has built-in)</td></tr><tr><td><code>:bodyClasses</code></td><td><code>data-slot</code> CSS</td></tr><tr><td><code>:maxOptions</code></td><td>no equivalent</td></tr><tr><td><code>#target=&quot;{ togglePopover }&quot;</code></td><td><code>#trigger</code>, with no click handler (<code>open</code> is now a boolean)</td></tr><tr><td><code>#prefix</code> / <code>#suffix</code></td><td>same (<code>#suffix</code> now replaces chevron)</td></tr><tr><td><code>#item-prefix</code> / <code>#item-suffix</code> slot props <code>{ active, selected, option }</code></td><td><code>{ item, query, selected }</code> — <code>option</code> is renamed and <code>active</code> is gone, so a carried-over <code>option.label</code> throws during render</td></tr></tbody></table><h3 id="the-v-model-payload-inverts" tabindex="-1">The v-model payload inverts <a class="header-anchor" href="#the-v-model-payload-inverts" aria-label="Permalink to “The v-model payload inverts”">​</a></h3><p><code>Autocomplete</code> took and emitted the <strong>whole option object</strong>; both replacements model the <strong>value only</strong> — <code>Combobox</code> is <code>string | number | null</code>, <code>MultiSelect</code> is <code>(string | number)[]</code>. Code that reads <code>country.value</code> off the model gets <code>undefined</code> rather than a type error, since the model was loosely typed.</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Autocomplete</span><span class="s_1i4ay4"> v-model</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">country</span><span class="s_w1p9wo">&quot;</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">options</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">countries</span><span class="s_w1p9wo">&quot;</span><span class="s_1jjt6x"> @</span><span class="s_1i4ay4">change</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">onChange</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"><span class="s_1th9sy">&lt;!-- country === { label: &#39;India&#39;, value: &#39;in&#39; } --&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Combobox</span><span class="s_1i4ay4"> v-model</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">country</span><span class="s_w1p9wo">&quot;</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">options</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">countries</span><span class="s_w1p9wo">&quot;</span><span class="s_1jjt6x"> @</span><span class="s_1i4ay4">update</span><span class="s_1jjt6x">:</span><span class="s_1i4ay4">model-value</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">onChange</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"><span class="s_1th9sy">&lt;!-- country === &#39;in&#39; --&gt;</span></span></code></pre></div><p>Still need the whole option — for its <code>description</code>, an id field, anything beyond the value? Listen to <code>@update:selectedOption</code>, which carries it:</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Combobox</span></span>
<span class="line"><span class="s_1i4ay4">  v-model</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">country</span><span class="s_w1p9wo">&quot;</span></span>
<span class="line"><span class="s_1jjt6x">  :</span><span class="s_1i4ay4">options</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">countries</span><span class="s_w1p9wo">&quot;</span></span>
<span class="line"><span class="s_1jjt6x">  @</span><span class="s_1i4ay4">update</span><span class="s_1jjt6x">:</span><span class="s_1i4ay4">selected-option</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_13ahmt">(</span><span class="s_fsg3al">option</span><span class="s_13ahmt">)</span><span class="s_50ecpt"> =&gt;</span><span class="s_13ahmt"> (</span><span class="s_22m8k2">label</span><span class="s_2ekfrt"> =</span><span class="s_22m8k2"> option</span><span class="s_1jjt6x">?.</span><span class="s_11933w">label</span><span class="s_50ecpt"> ??</span><span class="s_w1p9wo"> &#39;&#39;</span><span class="s_13ahmt">)</span><span class="s_w1p9wo">&quot;</span></span>
<span class="line"><span class="s_6am9cx">/&gt;</span></span></code></pre></div><h3 id="grouped-options-items-→-options" tabindex="-1">Grouped options: <code>items</code> → <code>options</code> <a class="header-anchor" href="#grouped-options-items-→-options" aria-label="Permalink to “Grouped options: items → options”">​</a></h3><p>The key holding a group&#39;s children is now <code>options</code>, matching the top-level prop. <code>Combobox</code> and <code>MultiSelect</code> throw and name the group if they find the old key, so this one is caught the first time the picker opens — but only then, not at build time. <code>Dropdown</code> and <code>ContextMenu</code> share the rename and fail the other way: the group is dropped in silence (see <a href="#dropdown-and-contextmenu">Dropdown and ContextMenu</a>).</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Autocomplete</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">options</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_13ahmt">[{</span><span class="s_r4oegk"> group</span><span class="s_1jjt6x">: </span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">Asia</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">, </span><span class="s_r4oegk">items</span><span class="s_1jjt6x">: </span><span class="s_13ahmt">[</span><span class="s_11933w">india</span><span class="s_1jjt6x">, </span><span class="s_11933w">japan</span><span class="s_13ahmt">]</span><span class="s_13ahmt"> }]</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Combobox</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">options</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_13ahmt">[{</span><span class="s_r4oegk"> group</span><span class="s_1jjt6x">: </span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">Asia</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">, </span><span class="s_r4oegk">options</span><span class="s_1jjt6x">: </span><span class="s_13ahmt">[</span><span class="s_11933w">india</span><span class="s_1jjt6x">, </span><span class="s_11933w">japan</span><span class="s_13ahmt">]</span><span class="s_13ahmt"> }]</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span></code></pre></div><h3 id="target-→-trigger-and-drop-the-click-handler" tabindex="-1"><code>#target</code> → <code>#trigger</code>, and drop the click handler <a class="header-anchor" href="#target-→-trigger-and-drop-the-click-handler" aria-label="Permalink to “#target → #trigger, and drop the click handler”">​</a></h3><p>The slot is renamed, and the wiring inside it changes. <code>Autocomplete</code> handed <code>#target</code> a <code>togglePopover</code> function you had to call yourself. <code>Combobox</code> and <code>MultiSelect</code> attach the open toggle to the <code>#trigger</code> element for you, so the handler is not just unnecessary — a <code>togglePopover()</code> carried through the rename throws <code>togglePopover is not a function</code> on every click. The popover still opens, because the component&#39;s own handler already ran, so this reads as &quot;works, but noisy&quot; until someone looks at the console.</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Autocomplete</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">options</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">fields</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;template #target=&quot;{ togglePopover }&quot;&gt;</span></span>
<span class="line"><span class="s_6am9cx">    &lt;Button label=&quot;Add filter&quot; @click=&quot;togglePopover()&quot; /&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;/template&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">Autocomplete</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Combobox</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">options</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">fields</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;template #trigger&gt;</span></span>
<span class="line"><span class="s_6am9cx">    &lt;Button label=&quot;Add filter&quot; /&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;/template&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">Combobox</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p><strong><code>open</code> changed from a function to a boolean, and that part is silent.</strong> On <code>#target</code> it was the function that opened the popover, so anything reading it as a value — <code>v-if=&quot;open&quot;</code>, <code>:class=&quot;{ &#39;rotate-180&#39;: open }&quot;</code> — was reading a function object and was <strong>always truthy</strong>. On <code>#trigger</code> it is the real open state, so those expressions start doing what they always looked like they did.</p><p><code>Combobox</code>&#39;s <code>#trigger</code> receives <code>{ open, disabled, query, selectedOption, displayValue, clear, setOpen }</code>. <code>MultiSelect</code>&#39;s receives <code>{ open, disabled, query, selectedOptions, clear, setOpen }</code> — plural, and with no <code>displayValue</code>. Use <code>setOpen</code> for a trigger that has to open the popover from somewhere other than its own click.</p><h3 id="the-trigger-shape-changed-—-pass-trigger-button-to-keep-v0-s" tabindex="-1">The trigger shape changed — pass <code>trigger=&quot;button&quot;</code> to keep v0&#39;s <a class="header-anchor" href="#the-trigger-shape-changed-—-pass-trigger-button-to-keep-v0-s" aria-label="Permalink to “The trigger shape changed — pass trigger=&quot;button&quot; to keep v0&#39;s”">​</a></h3><p><code>Autocomplete</code> rendered a button showing the selection, with the search box inside the popover. <code>Combobox</code> defaults to <code>trigger=&quot;input&quot;</code> — the trigger <em>is</em> the search field. Pass <code>trigger=&quot;button&quot;</code> to keep the old shape.</p><h2 id="formcontrol-type-autocomplete-removed" tabindex="-1">FormControl <code>type=&quot;autocomplete&quot;</code> (removed) <a class="header-anchor" href="#formcontrol-type-autocomplete-removed" aria-label="Permalink to “FormControl type=&quot;autocomplete&quot; (removed)”">​</a></h2><p><strong>This one is silent.</strong> <code>FormControl</code> is a dispatcher: with the <code>autocomplete</code> case gone, the type falls through to <code>TextInput</code> and is still forwarded as an html input type. The result is <code>&lt;input type=&quot;autocomplete&quot;&gt;</code>, which every browser renders as a plain text box — a picker that turned into a text field. No runtime error, and no build error in plain JS; TypeScript callers do get one, because <code>&#39;autocomplete&#39;</code> is no longer in the <code>type</code> union. A dev-only <code>console.error</code> names it.</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">FormControl</span><span class="s_1i4ay4"> type</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">autocomplete</span><span class="s_w1p9wo">&quot;</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">options</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">countries</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> v-model</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">country</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"><span class="s_1th9sy">&lt;!-- country === { label: &#39;India&#39;, value: &#39;in&#39; } --&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">FormControl</span><span class="s_1i4ay4"> type</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">combobox</span><span class="s_w1p9wo">&quot;</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">options</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">countries</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> v-model</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">country</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"><span class="s_1th9sy">&lt;!-- country === &#39;in&#39; --&gt;</span></span></code></pre></div><p>The v-model payload inverts here too, for the same reason as above. Or use the standalone <a href="./components/combobox"><code>Combobox</code></a>, which exposes the full set of props and slots without the wrapper.</p><h2 id="http-transport-and-the-frappeui-plugin" tabindex="-1">HTTP transport and the <code>FrappeUI</code> plugin <a class="header-anchor" href="#http-transport-and-the-frappeui-plugin" aria-label="Permalink to “HTTP transport and the FrappeUI plugin”">​</a></h2><p>v1 has one HTTP path. <code>frappeRequest</code> is it; <code>call</code> is a thin wrapper over it for the common &quot;POST to a whitelisted method&quot; case. <code>request</code>, <code>createCall</code> and <code>initSocket</code> are gone, and <code>app.use(FrappeUI)</code> is down to a single option.</p><table tabindex="0"><thead><tr><th>Before</th><th>After</th></tr></thead><tbody><tr><td><code>import { request }</code></td><td><code>import { frappeRequest }</code></td></tr><tr><td><code>createCall(options)</code></td><td>wrap <code>call</code> yourself, or use <code>frappeRequest</code></td></tr><tr><td><code>import { initSocket }</code></td><td>your own <code>io(...)</code> connection</td></tr><tr><td><code>app.use(FrappeUI, { config })</code></td><td><code>setConfig(key, value)</code> per entry</td></tr><tr><td><code>app.use(FrappeUI, { call })</code></td><td><code>import { call }</code> where you need it</td></tr><tr><td><code>this.$resources</code> (implicit)</td><td><code>app.use(FrappeUI, { resources: true })</code></td></tr></tbody></table><p>The first three are build failures — your bundler or type-check names them. The last three fail at runtime instead: a dropped <code>config</code> is applied nowhere, and reading <code>this.$call</code> or <code>this.$resources</code> throws with the fix in the message.</p><p><code>frappeRequest</code> is not a drop-in for <code>request</code>. Check three things at each call site you swap: the method defaults to <code>POST</code>, not <code>GET</code>; a URL that is not a path is prefixed with <code>/api/method/</code>; and it resolves with the response body&#39;s <code>message</code>, not the whole body. The shape you get back changes with no error.</p><h3 id="call-now-honours-setconfig" tabindex="-1"><code>call</code> now honours <code>setConfig</code> <a class="header-anchor" href="#call-now-honours-setconfig" aria-label="Permalink to “call now honours setConfig”">​</a></h3><p><code>call</code> built its own <code>fetch</code> and never read the config, so <code>requestBaseUrl</code> and <code>requestHeaders</code> were quietly ignored on every <code>call()</code> while <code>frappeRequest</code> respected them. That inconsistency is fixed, which means a <code>call</code> in an app that sets either one now behaves differently — usually the way you assumed it already did. Two knock-on effects worth checking:</p><ul><li>If you set <code>requestBaseUrl</code> for local dev against a remote site, <code>call</code> now goes to the remote site too, with <code>credentials: &#39;include&#39;</code>.</li><li>If you set <code>serverMessagesHandler</code>, <code>_server_messages</code> returned by a <code>call</code> now reach it. Previously only <code>frappeRequest</code> and the resources fed it, so expect toasts from paths that used to be silent.</li></ul><p><code>call</code>&#39;s signature, the value it resolves to, and the <code>{ response, status, error }</code> object passed to <code>onError</code> are all unchanged.</p><h3 id="the-plugin-s-config-option-is-gone" tabindex="-1">The plugin&#39;s <code>config</code> option is gone <a class="header-anchor" href="#the-plugin-s-config-option-is-gone" aria-label="Permalink to “The plugin&#39;s config option is gone”">​</a></h3><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">// Before</span></span>
<span class="line"><span class="s_22m8k2">app</span><span class="s_1jjt6x">.</span><span class="s_indoxt">use</span><span class="s_13ahmt">(</span><span class="s_22m8k2">FrappeUI</span><span class="s_1jjt6x">,</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_r4oegk">  config</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_r4oegk">    resourceFetcher</span><span class="s_1jjt6x">:</span><span class="s_22m8k2"> frappeRequest</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">    defaultListUrl</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">gameplan.extends.client.get_list</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">    systemTimezone</span><span class="s_1jjt6x">:</span><span class="s_22m8k2"> window</span><span class="s_1jjt6x">.</span><span class="s_11933w">system_timezone</span><span class="s_50ecpt"> ||</span><span class="s_40mev6"> null</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">  }</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">})</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">// After</span></span>
<span class="line"><span class="s_indoxt">setConfig</span><span class="s_13ahmt">(</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">resourceFetcher</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_22m8k2"> frappeRequest</span><span class="s_13ahmt">)</span></span>
<span class="line"><span class="s_indoxt">setConfig</span><span class="s_13ahmt">(</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">defaultListUrl</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">gameplan.extends.client.get_list</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt">)</span></span>
<span class="line"><span class="s_indoxt">setConfig</span><span class="s_13ahmt">(</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">systemTimezone</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_22m8k2"> window</span><span class="s_1jjt6x">.</span><span class="s_11933w">system_timezone</span><span class="s_50ecpt"> ||</span><span class="s_40mev6"> null</span><span class="s_13ahmt">)</span></span>
<span class="line"><span class="s_22m8k2">app</span><span class="s_1jjt6x">.</span><span class="s_indoxt">use</span><span class="s_13ahmt">(</span><span class="s_22m8k2">FrappeUI</span><span class="s_13ahmt">)</span></span></code></pre></div><p>Passing a removed option is not a type error if your <code>main.js</code> is plain JS, so the plugin logs a dev-mode warning naming the option it ignored. Note that <code>setConfig</code> only accepts keys of <code>FrappeUIConfig</code> — if you were passing a key that isn&#39;t one, it was never read and can be deleted.</p><h3 id="resources-is-opt-in" tabindex="-1"><code>$resources</code> is opt-in <a class="header-anchor" href="#resources-is-opt-in" aria-label="Permalink to “$resources is opt-in”">​</a></h3><p>The plugin used to install the v1 resources Options API mixin by default, so <code>this.$resources</code>, <code>$getResource</code>, <code>$getDocumentResource</code>, <code>$getDoc</code>, <code>$getListResource</code> and <code>$refetchResource</code> existed in any app that called <code>app.use(FrappeUI)</code>. It now installs only when asked:</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_22m8k2">app</span><span class="s_1jjt6x">.</span><span class="s_indoxt">use</span><span class="s_13ahmt">(</span><span class="s_22m8k2">FrappeUI</span><span class="s_1jjt6x">,</span><span class="s_13ahmt"> {</span><span class="s_r4oegk"> resources</span><span class="s_1jjt6x">:</span><span class="s_40mev6"> true</span><span class="s_13ahmt"> })</span></span></code></pre></div><p>Nothing changes for Composition API code — <code>createResource</code>, <code>createListResource</code> and <code>createDocumentResource</code> never went through the plugin. You need the option only if you declare a <code>resources: { … }</code> block in a component&#39;s options.</p><p>You will not have to work this out from a blank screen. A component that declares <code>resources</code> without the option throws on creation, naming itself and the fix. Vue routes that throw through its own error handling, which rethrows in dev and only logs in production, so the read is guarded too: reading <code>this.$resources</code> throws at the access in every build, straight into your own code. <code>resourcesPlugin</code> is still exported if you would rather install it directly.</p><h3 id="initsocket-is-gone" tabindex="-1"><code>initSocket</code> is gone <a class="header-anchor" href="#initsocket-is-gone" aria-label="Permalink to “initSocket is gone”">​</a></h3><p>It was a nine-line <code>io()</code> wrapper, and the plugin created one by default — which meant apps that also built their own socket held two live connections per page load. If you relied on the <code>$socket</code> global the plugin set, create the connection yourself:</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">io</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">socket.io-client</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> host</span><span class="s_2ekfrt"> =</span><span class="s_22m8k2"> window</span><span class="s_1jjt6x">.</span><span class="s_22m8k2">location</span><span class="s_1jjt6x">.</span><span class="s_11933w">hostname</span></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> port</span><span class="s_2ekfrt"> =</span><span class="s_22m8k2"> window</span><span class="s_1jjt6x">.</span><span class="s_22m8k2">location</span><span class="s_1jjt6x">.</span><span class="s_11933w">port</span><span class="s_50ecpt"> ?</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">:9000</span><span class="s_w1p9wo">&#39;</span><span class="s_50ecpt"> :</span><span class="s_w1p9wo"> &#39;&#39;</span></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> protocol</span><span class="s_2ekfrt"> =</span><span class="s_22m8k2"> port</span><span class="s_50ecpt"> ?</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">http</span><span class="s_w1p9wo">&#39;</span><span class="s_50ecpt"> :</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">https</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> siteName</span><span class="s_2ekfrt"> =</span><span class="s_edvzsf"> import</span><span class="s_1jjt6x">.</span><span class="s_1vt12c">meta</span><span class="s_1jjt6x">.</span><span class="s_22m8k2">env</span><span class="s_1jjt6x">.</span><span class="s_40mev6">DEV</span><span class="s_50ecpt"> ?</span><span class="s_22m8k2"> host</span><span class="s_50ecpt"> :</span><span class="s_22m8k2"> window</span><span class="s_1jjt6x">.</span><span class="s_11933w">site_name</span></span>
<span class="line"></span>
<span class="line"><span class="s_22m8k2">app</span><span class="s_1jjt6x">.</span><span class="s_22m8k2">config</span><span class="s_1jjt6x">.</span><span class="s_22m8k2">globalProperties</span><span class="s_1jjt6x">.</span><span class="s_11933w">$socket</span><span class="s_2ekfrt"> =</span><span class="s_indoxt"> io</span><span class="s_13ahmt">(</span></span>
<span class="line"><span class="s_w1p9wo">  \`</span><span class="s_20l85h">\${</span><span class="s_22m8k2">protocol</span><span class="s_20l85h">}</span><span class="s_2575z4">://</span><span class="s_20l85h">\${</span><span class="s_22m8k2">host</span><span class="s_20l85h">}\${</span><span class="s_22m8k2">port</span><span class="s_20l85h">}</span><span class="s_2575z4">/</span><span class="s_20l85h">\${</span><span class="s_22m8k2">siteName</span><span class="s_20l85h">}</span><span class="s_w1p9wo">\`</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">  {</span><span class="s_r4oegk"> withCredentials</span><span class="s_1jjt6x">:</span><span class="s_40mev6"> true</span><span class="s_13ahmt"> }</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">)</span></span></code></pre></div><p>Until you do, reading <code>this.$socket</code> throws with that instruction rather than returning <code>undefined</code> and crashing in whatever realtime handler reads it next. Assigning your own replaces the guard. The same applies to <code>$call</code>, the other global the plugin used to install — import <code>call</code> from <code>frappe-ui</code> instead.</p><h2 id="composables-and-directives-renamed" tabindex="-1">Composables and directives renamed <a class="header-anchor" href="#composables-and-directives-renamed" aria-label="Permalink to “Composables and directives renamed”">​</a></h2><p>Three groups of root exports changed names. All of them fail at the import, so the build lists every call site — but one of them has a quiet second half, and that is the one to read.</p><h3 id="usetheme-→-usecolorscheme" tabindex="-1"><code>useTheme</code> → <code>useColorScheme</code> <a class="header-anchor" href="#usetheme-→-usecolorscheme" aria-label="Permalink to “useTheme → useColorScheme”">​</a></h3><p><code>theme</code> means color tone everywhere else in the library (<code>theme=&quot;blue&quot;</code> on a Button), so the light/dark composable gives the word back.</p><table tabindex="0"><thead><tr><th>Before</th><th>After</th></tr></thead><tbody><tr><td><code>useTheme()</code></td><td><code>useColorScheme()</code></td></tr><tr><td><code>Theme</code> type</td><td><code>ColorScheme</code> type</td></tr><tr><td><code>currentTheme</code></td><td><code>colorScheme</code> — read-only</td></tr><tr><td><code>setTheme(t)</code></td><td><code>setColorScheme(t)</code></td></tr><tr><td><code>toggleTheme()</code></td><td><code>toggleColorScheme()</code></td></tr><tr><td><code>getSystemTheme()</code></td><td><code>resolvedColorScheme()</code>, imported from the root</td></tr><tr><td><code>initializeTheme()</code></td><td>removed — <code>useColorScheme()</code> initializes itself</td></tr></tbody></table><p>The read-only <code>colorScheme</code> is the quiet part. The ref was only a third of the state; the <code>data-theme</code> attribute and the <code>theme</code> key in <code>localStorage</code> are the other two. Assigning to the old writable ref moved the ref and left the document and the stored value behind, so the app desynced with no error.</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">// Before — moved the ref, desynced the page</span></span>
<span class="line"><span class="s_252irl">const</span><span class="s_1jjt6x"> {</span><span class="s_295sjd"> currentTheme</span><span class="s_1jjt6x"> }</span><span class="s_2ekfrt"> =</span><span class="s_indoxt"> useTheme</span><span class="s_13ahmt">()</span></span>
<span class="line"><span class="s_22m8k2">currentTheme</span><span class="s_1jjt6x">.</span><span class="s_11933w">value</span><span class="s_2ekfrt"> =</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">dark</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">// After</span></span>
<span class="line"><span class="s_252irl">const</span><span class="s_1jjt6x"> {</span><span class="s_295sjd"> setColorScheme</span><span class="s_1jjt6x"> }</span><span class="s_2ekfrt"> =</span><span class="s_indoxt"> useColorScheme</span><span class="s_13ahmt">()</span></span>
<span class="line"><span class="s_indoxt">setColorScheme</span><span class="s_13ahmt">(</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">dark</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt">)</span></span></code></pre></div><p>The <code>data-theme</code> attribute and the <code>theme</code> localStorage key keep their names, so app CSS targeting <code>[data-theme=&#39;dark&#39;]</code> and saved user preferences still work.</p><h3 id="scroll-container-nine-members-become-two" tabindex="-1">Scroll container: nine members become two <a class="header-anchor" href="#scroll-container-nine-members-become-two" aria-label="Permalink to “Scroll container: nine members become two”">​</a></h3><p><code>useScrollContainer</code> published nine members for the two things apps do: read the shell&#39;s scroll element, and know whether it has been scrolled.</p><table tabindex="0"><thead><tr><th>Before</th><th>After</th></tr></thead><tbody><tr><td><code>activeScrollContainer</code></td><td><code>shellScrollContainer</code></td></tr><tr><td><code>getScrollContainer()</code></td><td><code>shellScrollContainer.value</code></td></tr><tr><td><code>useScrollContainer().isScrolled</code></td><td><code>useShellScrolled({ threshold })</code></td></tr><tr><td><code>scrollTo(options)</code> / <code>scrollToTop()</code></td><td>call them on <code>shellScrollContainer.value</code></td></tr><tr><td><code>registerScrollContainer</code> / <code>unregisterScrollContainer</code></td><td>removed — internal to the two shells</td></tr><tr><td><code>UseScrollContainer</code> / <code>UseScrollContainerOptions</code></td><td>removed</td></tr></tbody></table><p><code>useShellScrolled()</code> returns the boolean ref directly, not an object:</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">// Before</span></span>
<span class="line"><span class="s_252irl">const</span><span class="s_1jjt6x"> {</span><span class="s_295sjd"> isScrolled</span><span class="s_1jjt6x"> }</span><span class="s_2ekfrt"> =</span><span class="s_indoxt"> useScrollContainer</span><span class="s_13ahmt">({</span><span class="s_r4oegk"> threshold</span><span class="s_1jjt6x">:</span><span class="s_40mev6"> 12</span><span class="s_13ahmt"> })</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">// After</span></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> isScrolled</span><span class="s_2ekfrt"> =</span><span class="s_indoxt"> useShellScrolled</span><span class="s_13ahmt">({</span><span class="s_r4oegk"> threshold</span><span class="s_1jjt6x">:</span><span class="s_40mev6"> 12</span><span class="s_13ahmt"> })</span></span></code></pre></div><p>The <code>shell</code> prefix is load-bearing: both resolve only while a <code>DesktopShell</code> or a <code>MobileShell</code> is mounted. Without one, <code>useShellScrolled</code> stays <code>false</code> and warns once in development.</p><h3 id="directives-vfocus-and-vonoutsideclick" tabindex="-1">Directives: <code>vFocus</code> and <code>vOnOutsideClick</code> <a class="header-anchor" href="#directives-vfocus-and-vonoutsideclick" aria-label="Permalink to “Directives: vFocus and vOnOutsideClick”">​</a></h3><p><code>&lt;script setup&gt;</code> auto-registers a directive only when the imported binding is spelled <code>vFoo</code>, so the old names had to be aliased at every call site.</p><table tabindex="0"><thead><tr><th>Before</th><th>After</th></tr></thead><tbody><tr><td><code>focusDirective</code></td><td><code>vFocus</code></td></tr><tr><td><code>onOutsideClickDirective</code></td><td><code>vOnOutsideClick</code></td></tr><tr><td><code>visibilityDirective</code></td><td>removed, no replacement</td></tr></tbody></table><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1i4ay4"> setup</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_22m8k2">onOutsideClickDirective</span><span class="s_2ekfrt"> as</span><span class="s_4q1z3w"> vOnOutsideClick</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1i4ay4"> setup</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">vOnOutsideClick</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><h2 id="usecall-a-throwing-beforesubmit-now-cancels-the-submit" tabindex="-1">useCall: a throwing <code>beforeSubmit</code> now cancels the submit <a class="header-anchor" href="#usecall-a-throwing-beforesubmit-now-cancels-the-submit" aria-label="Permalink to “useCall: a throwing beforeSubmit now cancels the submit”">​</a></h2><p>Previously a <code>beforeSubmit</code> hook that threw was caught and logged, and the request was <strong>sent anyway</strong>. Now the throw propagates: the request is not sent and <code>submit()</code> rejects with the hook&#39;s error.</p><p>This is a silent behavior change. If one of your <code>beforeSubmit</code> hooks can throw, the submit it used to let through now stops. Either handle the rejection at the call site or make the hook non-throwing to keep the old behavior. A hook that returns normally is unaffected — it still cannot stop the request.</p><p><code>beforeSubmit</code> may now be async (<code>() =&gt; void | Promise&lt;void&gt;</code>); it was always awaited, only the type said otherwise.</p><p><code>error</code> is untouched by a cancelled submit. The throw reaches you only through the rejected <code>submit()</code>, so <code>error</code> still holds the last <em>request&#39;s</em> error — an app that renders failures from <code>error</code> alone renders nothing when a hook cancels. This covers every place <code>beforeSubmit</code> is accepted: <code>useCall</code>, <code>useNewDoc</code>, and each entry in <code>useDoc</code>&#39;s <code>methods:</code>.</p><h2 id="pagemetaplugin-removed" tabindex="-1">pageMetaPlugin (removed) <a class="header-anchor" href="#pagemetaplugin-removed" aria-label="Permalink to “pageMetaPlugin (removed)”">​</a></h2><p><code>pageMetaPlugin</code> and the global mixin it installed are gone. A <code>pageMeta()</code> component option still compiles — it&#39;s a plain, unread object key — but nothing calls it anymore, so <code>document.title</code> and the favicon stop updating. This is a <strong>silent break</strong>: no error, no warning, the page just stops retitling itself.</p><table tabindex="0"><thead><tr><th>Before</th><th>After</th></tr></thead><tbody><tr><td><code>app.use(pageMetaPlugin)</code></td><td>delete — nothing to install</td></tr><tr><td><code>pageMeta() { return { title, emoji } }</code></td><td><code>usePageMeta(() =&gt; ({ title, emoji }))</code> in <code>setup()</code></td></tr></tbody></table><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_edvzsf">export</span><span class="s_edvzsf"> default</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_indoxt">  pageMeta</span><span class="s_13ahmt">()</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_29n2kq">    return</span><span class="s_13ahmt"> { </span><span class="s_r4oegk">title</span><span class="s_1jjt6x">:</span><span class="s_118ozv"> this</span><span class="s_1jjt6x">.</span><span class="s_11933w">pageTitle</span><span class="s_1jjt6x">,</span><span class="s_r4oegk"> emoji</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">🌈</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> }</span></span>
<span class="line"><span class="s_13ahmt">  }</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">}</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1i4ay4"> setup</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">usePageMeta</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_indoxt">usePageMeta</span><span class="s_13ahmt">(()</span><span class="s_50ecpt"> =&gt;</span><span class="s_13ahmt"> ({</span><span class="s_r4oegk"> title</span><span class="s_1jjt6x">:</span><span class="s_22m8k2"> pageTitle</span><span class="s_1jjt6x">.</span><span class="s_11933w">value</span><span class="s_1jjt6x">,</span><span class="s_r4oegk"> emoji</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">🌈</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> }))</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p><code>usePageMeta</code> works the same everywhere — see the <a href="./other/composables#usepagemeta">composables page</a>.</p><h2 id="commandpalette" tabindex="-1">CommandPalette <a class="header-anchor" href="#commandpalette" aria-label="Permalink to “CommandPalette”">​</a></h2><p><code>show</code> is renamed to <code>open</code>, matching the rest of the library&#39;s overlay vocabulary. This is a <strong>silent break</strong>: Vue accepts the unknown <code>show</code> prop with no error, so the palette just never opens.</p><p><code>searchQuery</code> is renamed to <code>query</code>, the name <code>Combobox</code> and <code>MultiSelect</code> already use for the same controlled search text. Same silent break: the unknown <code>searchQuery</code> prop is accepted, so the palette holds its own query and yours never updates.</p><table tabindex="0"><thead><tr><th>Before</th><th>After</th></tr></thead><tbody><tr><td><code>v-model:show=&quot;show&quot;</code></td><td><code>v-model:open=&quot;open&quot;</code></td></tr><tr><td><code>v-model:search-query=&quot;q&quot;</code></td><td><code>v-model:query=&quot;q&quot;</code></td></tr><tr><td><code>@update:searchQuery=&quot;onSearch&quot;</code></td><td><code>@update:query=&quot;onSearch&quot;</code></td></tr></tbody></table><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">CommandPalette</span><span class="s_1i4ay4"> v-model</span><span class="s_1jjt6x">:</span><span class="s_1i4ay4">show</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">show</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> v-model</span><span class="s_1jjt6x">:</span><span class="s_1i4ay4">search-query</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">q</span><span class="s_w1p9wo">&quot;</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">groups</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">groups</span><span class="s_w1p9wo">&quot;</span><span class="s_1jjt6x"> @</span><span class="s_1i4ay4">select</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">onSelect</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">CommandPalette</span><span class="s_1i4ay4"> v-model</span><span class="s_1jjt6x">:</span><span class="s_1i4ay4">open</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">open</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> v-model</span><span class="s_1jjt6x">:</span><span class="s_1i4ay4">query</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">q</span><span class="s_w1p9wo">&quot;</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">groups</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">groups</span><span class="s_w1p9wo">&quot;</span><span class="s_1jjt6x"> @</span><span class="s_1i4ay4">select</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">onSelect</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span></code></pre></div><p><code>Mod+K</code> is registered internally through <code>useShortcut</code> (v0 used its own <code>keydown</code> listener on <code>window</code>). Delete any app-level listener you added on top of it.</p><h2 id="keyboardshortcut" tabindex="-1">KeyboardShortcut <a class="header-anchor" href="#keyboardshortcut" aria-label="Permalink to “KeyboardShortcut”">​</a></h2><p>The deprecated <code>shortcut</code> prop, and the unused <code>meta</code> / <code>ctrl</code> / <code>shift</code> / <code>alt</code> boolean props, are removed. Use <code>combo</code> — a string like <code>&quot;Mod+Shift+K&quot;</code>.</p><table tabindex="0"><thead><tr><th>Before</th><th>After</th></tr></thead><tbody><tr><td><code>&lt;KeyboardShortcut shortcut=&quot;Mod+K&quot; /&gt;</code></td><td><code>&lt;KeyboardShortcut combo=&quot;Mod+K&quot; /&gt;</code></td></tr><tr><td><code>&lt;KeyboardShortcut ctrl shift&gt;K&lt;/KeyboardShortcut&gt;</code></td><td><code>&lt;KeyboardShortcut combo=&quot;Mod+Shift+K&quot; /&gt;</code></td></tr></tbody></table><p>Both are <strong>silent breaks</strong> at runtime: the removed props fall through onto the rendered <code>&lt;span&gt;</code> as plain HTML attributes, so <code>shortcut=&quot;Mod+K&quot;</code> renders an empty chip and <code>ctrl shift</code> renders the key with no modifier glyphs. Only a type-check names the call sites.</p><h3 id="matchesshortcut-is-no-longer-exported" tabindex="-1"><code>matchesShortcut</code> is no longer exported <a class="header-anchor" href="#matchesshortcut-is-no-longer-exported" aria-label="Permalink to “matchesShortcut is no longer exported”">​</a></h3><p><code>import { matchesShortcut } from &#39;frappe-ui&#39;</code> fails at the build. Its own doc comment said it was exported for unit tests only. Register a shortcut with <code>useShortcut</code> instead of matching a <code>KeyboardEvent</code> by hand.</p><h2 id="pageheadermobile-family-slot-names" tabindex="-1">PageHeaderMobile family: slot names <a class="header-anchor" href="#pageheadermobile-family-slot-names" aria-label="Permalink to “PageHeaderMobile family: slot names”">​</a></h2><p><code>PageHeaderMobile</code>&#39;s <code>#left</code>/<code>#right</code> and <code>PageHeaderMobileTitle</code>&#39;s <code>#icon</code> are renamed to the shared <code>#prefix</code>/<code>#suffix</code> vocabulary (see <a href="https://github.com/frappe/frappe-ui/blob/main/PHILOSOPHY.md" target="_blank" rel="noreferrer">PHILOSOPHY.md P6</a>). This is a <strong>silent break</strong>: Vue drops content passed to an unknown slot name with no error or warning — the back button, title icon, or trailing action just stops rendering.</p><table tabindex="0"><thead><tr><th>Before</th><th>After</th></tr></thead><tbody><tr><td><code>PageHeaderMobile</code> <code>#left</code></td><td><code>#prefix</code></td></tr><tr><td><code>PageHeaderMobile</code> <code>#right</code></td><td><code>#suffix</code></td></tr><tr><td><code>PageHeaderMobileTitle</code> <code>#icon</code></td><td><code>#prefix</code></td></tr></tbody></table><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">PageHeaderMobile</span><span class="s_1i4ay4"> title</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">Space</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;template #left&gt;&lt;BackButton /&gt;&lt;/template&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;template #right&gt;&lt;Button icon=&quot;lucide-more-horizontal&quot; /&gt;&lt;/template&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">PageHeaderMobile</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">PageHeaderMobileTitle</span><span class="s_1i4ay4"> title</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">Space</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;template #icon&gt;&lt;SpaceIcon /&gt;&lt;/template&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">PageHeaderMobileTitle</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">PageHeaderMobile</span><span class="s_1i4ay4"> title</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">Space</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;template #prefix&gt;&lt;BackButton /&gt;&lt;/template&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;template #suffix&gt;&lt;Button icon=&quot;lucide-more-horizontal&quot; /&gt;&lt;/template&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">PageHeaderMobile</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">PageHeaderMobileTitle</span><span class="s_1i4ay4"> title</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">Space</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;template #prefix&gt;&lt;SpaceIcon /&gt;&lt;/template&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">PageHeaderMobileTitle</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p>Grep for <code>#left</code>, <code>#right</code>, and <code>#icon</code> on these two components specifically — other components (e.g. <code>ListView</code>&#39;s footer) have their own unrelated <code>#left</code>/ <code>#right</code> slots that are unaffected.</p><h3 id="frappeuiproviderprops-is-deleted" tabindex="-1"><code>FrappeUIProviderProps</code> is deleted <a class="header-anchor" href="#frappeuiproviderprops-is-deleted" aria-label="Permalink to “FrappeUIProviderProps is deleted”">​</a></h3><p>The type was exported but never wired to the component, so it described props <code>FrappeUIProvider</code> did not accept. It is removed in <code>1.0.0</code> with no replacement. This one is <strong>loud</strong> — <code>import type { FrappeUIProviderProps } from &#39;frappe-ui&#39;</code> fails the type-check. <code>FrappeUIProvider</code> itself is unchanged and still exported.</p><h2 id="charts" tabindex="-1">Charts <a class="header-anchor" href="#charts" aria-label="Permalink to “Charts”">​</a></h2><p>Only for apps already on <code>frappe-ui/charts</code> from <code>1.0.0-beta.42</code> or later — the subpath did not exist before that. The family is new in v1, so an app coming from v0 has nothing to migrate here; the older <code>config</code>-object family is covered by the &quot;Charts (v1)&quot; section above.</p><p>Eight charts renamed their mark emit to <code>select</code>, collapsing six old names into one. This is a <strong>silent break</strong>: Vue attaches a listener for an emit the component no longer declares as a plain attribute, so the handler stops firing with no error and no warning. The payload is unchanged, so only the name moves.</p><table tabindex="0"><thead><tr><th>Before</th><th>After</th></tr></thead><tbody><tr><td><code>AreaChart</code> <code>@datapoint-click</code></td><td><code>@select</code></td></tr><tr><td><code>BarChart</code> <code>@datapoint-click</code></td><td><code>@select</code></td></tr><tr><td><code>LineChart</code> <code>@datapoint-click</code></td><td><code>@select</code></td></tr><tr><td><code>DonutChart</code> <code>@slice-click</code></td><td><code>@select</code></td></tr><tr><td><code>FunnelChart</code> <code>@stage-click</code></td><td><code>@select</code></td></tr><tr><td><code>HeatmapChart</code> <code>@cell-click</code></td><td><code>@select</code></td></tr><tr><td><code>SankeyChart</code> <code>@link-click</code></td><td><code>@select</code></td></tr><tr><td><code>ScatterChart</code> <code>@point-click</code></td><td><code>@select</code></td></tr></tbody></table><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">BarChart</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">data</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">rows</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> x</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">warehouse</span><span class="s_w1p9wo">&quot;</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">y</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_13ahmt">[</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">picked</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt">]</span><span class="s_w1p9wo">&quot;</span><span class="s_1jjt6x"> @</span><span class="s_1i4ay4">datapoint-click</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">open</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">DonutChart</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">data</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">rows</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> category</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">channel</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> value</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">sessions</span><span class="s_w1p9wo">&quot;</span><span class="s_1jjt6x"> @</span><span class="s_1i4ay4">slice-click</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">open</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">SankeyChart</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">data</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">rows</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> source</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">from</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> target</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">to</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> value</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">amount</span><span class="s_w1p9wo">&quot;</span><span class="s_1jjt6x"> @</span><span class="s_1i4ay4">link-click</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">open</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">BarChart</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">data</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">rows</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> x</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">warehouse</span><span class="s_w1p9wo">&quot;</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">y</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_13ahmt">[</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">picked</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt">]</span><span class="s_w1p9wo">&quot;</span><span class="s_1jjt6x"> @</span><span class="s_1i4ay4">select</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">open</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">DonutChart</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">data</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">rows</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> category</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">channel</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> value</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">sessions</span><span class="s_w1p9wo">&quot;</span><span class="s_1jjt6x"> @</span><span class="s_1i4ay4">select</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">open</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">SankeyChart</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">data</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">rows</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> source</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">from</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> target</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">to</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> value</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">amount</span><span class="s_w1p9wo">&quot;</span><span class="s_1jjt6x"> @</span><span class="s_1i4ay4">select</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">open</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span></code></pre></div><p><code>select</code> also fires on Enter and Space over the plot&#39;s keyboard cursor, which is why the old names had to go — they described the mouse, not the behavior.</p><p>Grep for <code>datapoint-click</code>, <code>slice-click</code>, <code>stage-click</code>, <code>cell-click</code>, <code>link-click</code> and <code>point-click</code>, and for the camelCase spellings in render functions and <code>h()</code> props.</p><p>The rest of the family&#39;s breaks are loud — the build or the type-check reports them. <code>ChartTheme</code> is <code>ChartTokens</code>, <code>useChartTheme</code> is <code>useChartTokens</code> and it returns <code>{ tokens }</code> instead of <code>{ theme }</code>, and the <code>ColorScheme</code> type this subpath exported is now <code>ResolvedColorScheme</code>. <code>formatValue</code>, <code>formatDate</code>, <code>formatLabel</code>, <code>formatPercent</code>, <code>formatAxisValue</code>, <code>currentColorScheme</code> and <code>resolveChartTheme</code> are no longer exported.</p><h2 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to “FAQ”">​</a></h2><p><strong>Will my CSS break?</strong> In two ways. Where component structure changed, components expose <code>data-*</code> hooks (<code>data-slot</code>, <code>data-state</code>, <code>data-size</code>, <code>data-variant</code>) — audit selectors that targeted tags or classes. Separately, the token vocabulary moved: removed radius aliases and the shifted ink scales emit no CSS at all, with no build or type error. Run the <a href="#tokens">token codemod</a> before you audit anything by hand.</p><p><strong>Do I have to run the codemod?</strong> Yes, if you use Tailwind utilities from the frappe-ui preset. It is the only mechanical step in this guide — every component, prop and slot rename is a hand edit.</p><p><strong>Report bugs:</strong> <a href="https://github.com/frappe/frappe-ui/issues/new" target="_blank" rel="noreferrer">file an issue</a> with the <code>v1-beta</code> label. Include the component name, before/after code, version, and a repro.</p>`,458)])])}const _=a(p,[["render",o]]);export{u as __pageData,_ as default};
